1	// Saved-card / off-session charging primitives for subscription renewals.
2	//
3	// WHY THIS FILE EXISTS
4	// Until now a renewal could only debit the wallet (`worker/billing.ts` ->
5	// `debitWallet`). A customer with a perfectly good card on file was suspended the
6	// moment their wallet emptied, because `User.stripePaymentMethodId` was never
7	// written and never read. Everything needed to charge a card lives here; the
8	// worker owns the *policy* (when to retry, when to suspend), this module owns the
9	// *mechanics* (attach a card, charge it, credit the wallet for what it paid).
10	//
11	// THE MONEY MODEL — identical to checkout, deliberately
12	// Checkout applies wallet credit first and puts only the remainder on the card
13	// (`lib/wallet-split.ts`). Renewals now do the same: the card is charged the
14	// remainder, that exact amount is CREDITED to the wallet, and the existing
15	// CAS-guarded renewal transaction debits the FULL renewal from the wallet. So the
16	// wallet is always the thing that pays the bill and the card is always just a way
17	// to fund the wallet — one money path, already proven, and a partial failure can
18	// never half-apply a renewal.
19	//
20	// Plain server module (NOT "use server"): imported by the worker, by server
21	// actions and by server components. `lib/stripe.ts` is not modified by this file.
22	
23	import type Stripe from "stripe";
24	import { db } from "./db";
25	import { stripe, stripeConfigured, stripePublishableKey, EMBEDDED_REQUEST_OPTS, CUSTOM_CHECKOUT_UI_MODE, type EmbeddedCheckout } from "./stripe";
26	import { STRIPE_MIN_CENTS } from "./wallet-split";
27	import { invoiceCreateData } from "./invoices";
28	// NOTE: no pricing imports here on purpose. `vpsTerm`, `vpsTermPriceCents` and
29	// `extraDiskCentsAt` were still imported after `renewalCharge` moved out to
30	// ./renewal-charge, leaving this file holding every ingredient of the renewal
31	// formula and nothing that used them — an invitation to write the second copy that
32	// lib/renewal-quote.ts documents two incidents about. The one formula lives in
33	// ./renewal-charge and is re-exported below.
34	
35	/* ------------------------------------------------------------------ *
36	 * Small shared helpers
37	 * ------------------------------------------------------------------ */
38	
39	function appBase(): string {
40	  return process.env.APP_URL ?? "http://localhost:3000";
41	}
42	
43	/** Audit actions used to decide whether an unclaimed Stripe card may be adopted. */
44	export const CARD_SETUP_STARTED = "card.setup_started";
45	export const CARD_REMOVED = "card.removed";
46	export const CARD_SET_PRIMARY = "card.set_primary";
47	
48	/** How long a "I clicked Add card" intent stays good for the adoption backstop. */
49	const SETUP_INTENT_TTL_DAYS = 7;
50	
51	export type CardDisplay = {
52	  brand: string | null;
53	  last4: string | null;
54	  expMonth: number | null;
55	  expYear: number | null;
56	};
57	
58	/** "Visa ···· 4242, expires 04/28" — one formatter for UI, email and audit text. */
59	export function cardDisplayLabel(card: CardDisplay): string | null {
60	  if (!card.last4) return null;
61	  const brand = brandLabel(card.brand);
62	  const expiry =
63	    card.expMonth && card.expYear
64	      ? `, expires ${String(card.expMonth).padStart(2, "0")}/${String(card.expYear).slice(-2)}`
65	      : "";
66	  return `${brand} ···· ${card.last4}${expiry}`;
67	}
68	
69	/** Stripe brand ids are lowercase slugs ("visa", "amex", "unionpay"). */
70	export function brandLabel(brand: string | null | undefined): string {
71	  const map: Record<string, string> = {
72	    visa: "Visa",
73	    mastercard: "Mastercard",
74	    amex: "American Express",
75	    discover: "Discover",
76	    diners: "Diners Club",
77	    jcb: "JCB",
78	    unionpay: "UnionPay",
79	    cartes_bancaires: "Cartes Bancaires",
80	    eftpos_au: "Eftpos",
81	    link: "Link",
82	  };
83	  if (!brand) return "Card";
84	  return map[brand] ?? brand.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
85	}
86	
87	/**
88	 * A card is valid THROUGH the last day of its expiry month, so it stops working
89	 * at the first instant of the following month. Getting this off by a month would
90	 * either nag customers a month early or warn them after the renewal already failed.
91	 */
92	export function cardExpiresAt(expMonth: number, expYear: number): Date {
93	  return new Date(Date.UTC(expYear, expMonth, 1));
94	}
95	
96	/* ------------------------------------------------------------------ *
97	 * Renewal pricing — ONE formula, two callers
98	 * ------------------------------------------------------------------ */
99	
100	/**
101	 * What a renewal costs. Lives here (rather than being copied a third time)
102	 * because BOTH the worker sweep and the customer-facing "settle the balance"
103	 * link have to quote the same number — `renewNow` and the sweep already carry
104	 * the comment "the two renewal paths must never disagree", and a self-service
105	 * pay link that quotes a different total than the sweep charges is exactly how
106	 * that goes wrong.
107	 *
108	 * Pure: prices are passed in so the worker can read the admin settings once per
109	 * sweep instead of once per server.
110	 */
111	// `renewalCharge` and its types now live in ./renewal-charge — a pure module with
112	// no SDK imports, so client components can price a renewal without pulling the
113	// Stripe SDK and nodemailer into the browser bundle. Re-exported here so every
114	// existing server-side importer keeps working unchanged.
115	export { renewalCharge, type RenewalCharge, type PricedServer } from "./renewal-charge";
116	
117	/* ------------------------------------------------------------------ *
118	 * Stripe customer + saving a card
119	 * ------------------------------------------------------------------ */
120	
121	export type CardUser = {
122	  id: string;
123	  email: string;
124	  name?: string | null;
125	  stripeCustomerId: string | null;
126	  stripePaymentMethodId: string | null;
127	};
128	
129	/** True when this account can actually be charged off-session right now. */
130	export function hasChargeableCard(user: {
131	  stripeCustomerId: string | null;
132	  stripePaymentMethodId: string | null;
133	}): boolean {
134	  return stripeConfigured() && !!user.stripeCustomerId && !!user.stripePaymentMethodId;
135	}
136	
137	/**
138	 * Get-or-create the Stripe customer for an account and remember its id.
139	 *
140	 * `User.stripeCustomerId` has no UNIQUE constraint (the schema is frozen), so two
141	 * concurrent "Add card" clicks could otherwise mint two Stripe customers for one
142	 * person and strand the card on whichever one lost. The idempotency key — derived
143	 * only from our own user id — is what stops that: Stripe replays the first
144	 * customer instead of creating a second.
145	 */
146	export async function ensureStripeCustomer(user: CardUser): Promise<string> {
147	  if (user.stripeCustomerId) return user.stripeCustomerId;
148	  const fresh = await db.user.findUnique({
149	    where: { id: user.id },
150	    select: { stripeCustomerId: true },
151	  });
152	  if (fresh?.stripeCustomerId) return fresh.stripeCustomerId;
153	
154	  const customer = await stripe().customers.create(
155	    {
156	      email: user.email,
157	      name: user.name || undefined,
158	      metadata: { nxeonUserId: user.id },
159	    },
160	    { idempotencyKey: `nxeon_customer_${user.id}` },
161	  );
162	  await db.user.update({ where: { id: user.id }, data: { stripeCustomerId: customer.id } });
163	  return customer.id;
164	}
165	
166	/**
167	 * Hosted Checkout session in `mode: "setup"` — how a customer saves a card.
168	 *
169	 * Checkout rather than Stripe Elements because there is no Elements/Stripe.js
170	 * integration anywhere in this codebase and no publishable key plumbed to the
171	 * browser; a redirect to Stripe's own page reuses the exact flow that already
172	 * takes money for deploys, upgrades and top-ups.
173	 *
174	 * `usage: "off_session"` is load-bearing: it records a mandate that covers the
175	 * unattended renewal charges we make later. Without it many issuers (and every
176	 * SCA-regulated card) reject the first off-session charge outright, which would
177	 * turn "saved card" into "card that is declined once a month".
178	 */
179	export async function createCardSetupSession(
180	  user: CardUser,
181	  returnPath = "/dashboard/billing",
182	): Promise<EmbeddedCheckout | null> {
183	  if (!stripeConfigured()) return null;
184	  const customerId = await ensureStripeCustomer(user);
185	  const base = appBase();
186	  const session = await stripe().checkout.sessions.create({
187	    mode: "setup",
188	    // Custom Checkout (`ui_mode: "elements"`), the same mode every payment
189	    // session on the platform was migrated to (see the block comment above
190	    // CUSTOM_CHECKOUT_UI_MODE in lib/stripe.ts) — mounted client-side via
191	    // CardSetupModal's `<PaymentElement>`, styled with the shared
192	    // STRIPE_APPEARANCE/STRIPE_FONTS rather than Stripe's default light
193	    // theme. This used to be `EMBEDDED_UI_MODE` ("embedded_page", Stripe's
194	    // own prebuilt page) — the one Stripe surface on the whole platform that
195	    // never got migrated when everything else did, which is exactly why
196	    // "Add a card" looked like an unstyled Stripe form. On completion Stripe
197	    // navigates to `return_url` (returnPath?card_setup=<id>) where the
198	    // existing finalize-on-return logic runs UNCHANGED — this is a pure
199	    // presentation change, same Checkout Session shape either way.
200	    ui_mode: CUSTOM_CHECKOUT_UI_MODE,
201	    customer: customerId,
202	    payment_method_types: ["card"],
203	    setup_intent_data: { metadata: { nxeonUserId: user.id } },
204	    metadata: { nxeonUserId: user.id, nxeonCardSetup: "1" },
205	    // returnPath may already carry a query (e.g. the Deploy hub's ?product=hosting),
206	    // so append card_setup with the correct separator.
207	    return_url: `${base}${returnPath}${returnPath.includes("?") ? "&" : "?"}card_setup={CHECKOUT_SESSION_ID}`,
208	  }, EMBEDDED_REQUEST_OPTS);
209	  return session.client_secret ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : null;
210	}
211	
212	/**
213	 * Copy the PRIMARY PaymentCard row's fields onto `User`'s mirror columns — the
214	 * one place that keeps the two in sync. Every renewal/dunning/off-session
215	 * charge path reads ONLY the `User` columns (`stripePaymentMethodId`,
216	 * `cardBrand`, etc.), never the `PaymentCard` table directly, so those paths
217	 * are completely unaffected by a customer having two cards or six: whichever
218	 * one is primary is always what they see. No primary left (the list is
219	 * empty) clears the mirror, the same as `clearCardColumns` always did.
220	 */
221	async function mirrorPrimaryCardToUser(userId: string, customerId?: string) {
222	  const primary = await db.paymentCard.findFirst({ where: { userId, isPrimary: true } });
223	  if (!primary) {
224	    await clearCardColumns(userId);
225	    return;
226	  }
227	  await db.user.update({
228	    where: { id: userId },
229	    data: {
230	      ...(customerId ? { stripeCustomerId: customerId } : {}),
231	      stripePaymentMethodId: primary.stripePaymentMethodId,
232	      cardBrand: primary.brand,
233	      cardLast4: primary.last4,
234	      cardExpMonth: primary.expMonth,
235	      cardExpYear: primary.expYear,
236	      cardExpiryNotifiedAt: null,
237	    },
238	  });
239	}
240	
241	/**
242	 * Add or refresh one card in the customer's list, then re-mirror the primary
243	 * onto `User`. A card that already exists (same Stripe payment method id —
244	 * e.g. Checkout re-attaching the same card after a browser refresh) is
245	 * updated in place, never duplicated. A BRAND NEW card becomes primary only
246	 * when the customer has no primary yet — adding a second card must never
247	 * silently switch what a pending renewal is about to charge.
248	 */
249	async function persistCard(userId: string, customerId: string, pm: Stripe.PaymentMethod) {
250	  const existing = await db.paymentCard.findUnique({ where: { stripePaymentMethodId: pm.id } });
251	  const hasPrimary = existing?.isPrimary || (await db.paymentCard.count({ where: { userId, isPrimary: true } })) > 0;
252	  await db.paymentCard.upsert({
253	    where: { stripePaymentMethodId: pm.id },
254	    create: {
255	      userId,
256	      stripePaymentMethodId: pm.id,
257	      brand: pm.card?.brand ?? null,
258	      last4: pm.card?.last4 ?? null,
259	      expMonth: pm.card?.exp_month ?? null,
260	      expYear: pm.card?.exp_year ?? null,
261	      isPrimary: !hasPrimary,
262	    },
263	    update: {
264	      brand: pm.card?.brand ?? null,
265	      last4: pm.card?.last4 ?? null,
266	      expMonth: pm.card?.exp_month ?? null,
267	      expYear: pm.card?.exp_year ?? null,
268	    },
269	  });
270	  await mirrorPrimaryCardToUser(userId, customerId);
271	}
272	
273	export type SavedCard = { brand: string | null; last4: string | null; expMonth: number | null; expYear: number | null };
274	
275	export type PaymentCardView = {
276	  id: string; brand: string | null; last4: string | null;
277	  expMonth: number | null; expYear: number | null; isPrimary: boolean;
278	};
279	
280	/** Every card a customer has saved, primary first — for the billing page's list. */
281	export async function listPaymentCards(userId: string): Promise<PaymentCardView[]> {
282	  const rows = await db.paymentCard.findMany({
283	    where: { userId },
284	    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
285	  });
286	  return rows.map((r) => ({
287	    id: r.id, brand: r.brand, last4: r.last4, expMonth: r.expMonth, expYear: r.expYear, isPrimary: r.isPrimary,
288	  }));
289	}
290	
291	/**
292	 * Make one of the customer's own cards primary and re-mirror it onto `User` —
293	 * the effect being that the NEXT renewal/off-session charge uses this card.
294	 * The whole flip is one transaction so a concurrent add/remove can never leave
295	 * two cards (or zero) marked primary.
296	 */
297	export async function setPrimaryPaymentCard(userId: string, cardId: string): Promise<{ ok?: true; error?: string }> {
298	  const card = await db.paymentCard.findUnique({ where: { id: cardId } });
299	  if (!card || card.userId !== userId) return { error: "Card not found." };
300	  if (!card.isPrimary) {
301	    await db.$transaction([
302	      db.paymentCard.updateMany({ where: { userId, isPrimary: true }, data: { isPrimary: false } }),
303	      db.paymentCard.update({ where: { id: cardId }, data: { isPrimary: true } }),
304	    ]);
305	    await mirrorPrimaryCardToUser(userId);
306	  }
307	  return { ok: true };
308	}
309	
310	/**
311	 * Remove ONE saved card by id (detach at Stripe first, same ordering
312	 * `detachSavedCard` uses and for the same reason — a method still attached at
313	 * Stripe when our row disappears is a method `adoptUnclaimedCards` could
314	 * re-adopt). Removing the primary card promotes the next-oldest remaining one
315	 * automatically, so a customer with two cards never ends up with neither
316	 * mirrored onto `User` by accident; removing the last card clears the mirror
317	 * exactly the way it always has.
318	 */
319	export async function removePaymentCard(userId: string, cardId: string): Promise<{ ok?: true; error?: string }> {
320	  const card = await db.paymentCard.findUnique({ where: { id: cardId } });
321	  if (!card || card.userId !== userId) return { error: "Card not found." };
322	  if (stripeConfigured()) {
323	    try {
324	      await stripe().paymentMethods.detach(card.stripePaymentMethodId);
325	    } catch (e) {
326	      const err = asStripeError(e);
327	      if (err?.code !== "resource_missing") {
328	        console.error("[cards] detach failed", e);
329	        return { error: "We couldn't remove the card just now. Please try again in a moment." };
330	      }
331	    }
332	  }
333	  await db.paymentCard.delete({ where: { id: cardId } });
334	  if (card.isPrimary) {
335	    const next = await db.paymentCard.findFirst({ where: { userId }, orderBy: { createdAt: "asc" } });
336	    if (next) await db.paymentCard.update({ where: { id: next.id }, data: { isPrimary: true } });
337	    await mirrorPrimaryCardToUser(userId);
338	  }
339	  return { ok: true };
340	}
341	
342	/**
343	 * Finalise a completed setup Checkout session: read the payment method off it,
344	 * make it the customer's default and mirror it onto the account.
345	 *
346	 * Verifies `metadata.nxeonUserId` against the caller. The session id travels in a
347	 * URL the customer can edit, so without that check a customer could paste someone
348	 * else's session id and attach their card to their own account.
349	 */
350	export async function saveCardFromSetupSession(
351	  sessionId: string,
352	  userId: string,
353	): Promise<{ card?: SavedCard; error?: string }> {
354	  if (!stripeConfigured()) return { error: "Card payments are not configured." };
355	  let session: Stripe.Checkout.Session;
356	  try {
357	    session = await stripe().checkout.sessions.retrieve(sessionId, { expand: ["setup_intent"] });
358	  } catch {
359	    return { error: "We couldn't read that card setup. Try adding the card again." };
360	  }
361	  if (session.mode !== "setup" || session.metadata?.nxeonUserId !== userId) {
362	    return { error: "That card setup doesn't belong to this account." };
363	  }
364	  if (session.status !== "complete") {
365	    return { error: "The card wasn't saved — the setup wasn't completed." };
366	  }
367	  const setupIntent = session.setup_intent as Stripe.SetupIntent | string | null;
368	  const pmRef =
369	    typeof setupIntent === "string" ? null : (setupIntent?.payment_method ?? null);
370	  const pmId = typeof pmRef === "string" ? pmRef : (pmRef?.id ?? null);
371	  const customerId =
372	    typeof session.customer === "string" ? session.customer : (session.customer?.id ?? null);
373	  if (!pmId || !customerId) return { error: "The card wasn't saved — no payment method came back." };
374	
375	  const pm = await stripe().paymentMethods.retrieve(pmId);
376	  // Checkout already attached the method to the customer; making it the default
377	  // means the adoption backstop below and anything Stripe-side pick the same card.
378	  await stripe()
379	    .customers.update(customerId, { invoice_settings: { default_payment_method: pmId } })
380	    .catch(() => {
381	      /* non-fatal: our own stripePaymentMethodId is the source of truth for charging */
382	    });
383	  await persistCard(userId, customerId, pm);
384	  return {
385	    card: {
386	      brand: pm.card?.brand ?? null,
387	      last4: pm.card?.last4 ?? null,
388	      expMonth: pm.card?.exp_month ?? null,
389	      expYear: pm.card?.exp_year ?? null,
390	    },
391	  };
392	}
393	
394	/**
395	 * Record the card off a completed `mode: "payment"` Checkout session.
396	 *
397	 * The twin of `saveCardFromSetupSession`, for the three "customer pays" sessions
398	 * (VPS order, game order, wallet top-up) that now carry
399	 * `payment_intent_data.setup_future_usage = "off_session"`. Stripe attaches the
400	 * payment method to the customer as part of that capture; this reads it back off
401	 * the PaymentIntent, makes it the customer's default and mirrors it onto the
402	 * account so the billing sweep can auto-charge renewals.
403	 *
404	 * Takes the ALREADY-RETRIEVED session (fulfil-checkout has it) rather than an id,
405	 * so the one session read is shared. The session from `retrieveCheckoutSession`
406	 * is unexpanded, so `payment_intent` is an id string — we retrieve the intent with
407	 * the payment method expanded.
408	 *
409	 * NEVER throws: the money has already moved and been fulfilled by the time this
410	 * runs, so a failure here must be inert. Writes the card mirror plus a
411	 * best-effort `card.saved` audit row (its own failure is swallowed, never
412	 * escalated — the mirror write is what matters). Returns `{ card }` on success
413	 * or `{ error }` otherwise.
414	 */
415	export async function saveCardFromPaymentSession(
416	  session: Stripe.Checkout.Session,
417	  userId: string,
418	): Promise<{ card?: SavedCard; error?: string }> {
419	  // Every caller (9 fulfilment paths — order, game order, hosting, email,
420	  // domain, resize, disk-expand, dedicated IP, plus the generic dispatch)
421	  // awaits this and then discards a returned `{error}` inside its own
422	  // `catch { /* best-effort */ }`, so a failure here was completely silent —
423	  // fulfilment succeeded, no card got saved, and nothing anywhere recorded
424	  // why. Found live 2026-09-24: 8 real paying customers had a successful
425	  // Stripe charge and zero saved card, each silently defaulting to the
426	  // faster "no card on file" dunning/suspend timeline despite having paid by
427	  // card. Every early return below now logs with the userId, so a repeat is
428	  // at least visible in the same place the existing catch already logged to
429	  // (this function's own console.error), not just a return value nobody read.
430	  if (!stripeConfigured()) {
431	    console.error(`[cards] could not save card for user ${userId}: Stripe not configured`);
432	    return { error: "Card payments are not configured." };
433	  }
434	  try {
435	    const piRef = session.payment_intent;
436	    const piId = typeof piRef === "string" ? piRef : (piRef?.id ?? null);
437	    const customerId =
438	      typeof session.customer === "string" ? session.customer : (session.customer?.id ?? null);
439	    if (!piId || !customerId) {
440	      console.error(
441	        `[cards] could not save card for user ${userId}: no payment_intent/customer on session ${session.id ?? "?"}`,
442	      );
443	      return { error: "No payment intent / customer on the session." };
444	    }
445	
446	    const pi = await stripe().paymentIntents.retrieve(piId, { expand: ["payment_method"] });
447	    const pmRef = pi.payment_method;
448	    const pmId = typeof pmRef === "string" ? pmRef : (pmRef?.id ?? null);
449	    if (!pmId) {
450	      console.error(`[cards] could not save card for user ${userId}: no payment_method on ${piId}`);
451	      return { error: "No payment method on the payment intent." };
452	    }
453	    // Expanded above, so usually already the object; fall back to a retrieve.
454	    const pm: Stripe.PaymentMethod =
455	      pmRef && typeof pmRef !== "string" ? pmRef : await stripe().paymentMethods.retrieve(pmId);
456	
457	    // Make it the customer's default — best-effort, exactly like the setup version;
458	    // our own `stripePaymentMethodId` is the source of truth for charging.
459	    await stripe()
460	      .customers.update(customerId, { invoice_settings: { default_payment_method: pmId } })
461	      .catch(() => {
462	        /* non-fatal */
463	      });
464	    await persistCard(userId, customerId, pm);
465	    // Found alongside the 2026-09-24 incident this function's own comment
466	    // documents: not just a silent-failure problem, a silent-SUCCESS one too.
467	    // A card saved through one of the 9 payment flows this feeds (wallet
468	    // top-up included) wrote no audit trail at all — `finalizeCardSetup`
469	    // (the dedicated "add a card" flow) logs `card.saved`, but a card
470	    // attached as a SIDE EFFECT of paying for something never did, so an
471	    // investigation into "where did this customer's card come from / go"
472	    // had no record to find for the majority of real card saves. Detail
473	    // says "via payment" specifically so it reads differently from the
474	    // setup-flow's own `card.saved` rows in the same log.
475	    await db.auditLog
476	      .create({
477	        data: {
478	          userId,
479	          action: "card.saved",
480	          detail: `${cardDisplayLabel({
481	            brand: pm.card?.brand ?? null,
482	            last4: pm.card?.last4 ?? null,
483	            expMonth: pm.card?.exp_month ?? null,
484	            expYear: pm.card?.exp_year ?? null,
485	          })} (via payment)`,
486	        },
487	      })
488	      .catch((e) => console.error(`[cards] card.saved audit log failed for ${userId}`, e));
489	    return {
490	      card: {
491	        brand: pm.card?.brand ?? null,
492	        last4: pm.card?.last4 ?? null,
493	        expMonth: pm.card?.exp_month ?? null,
494	        expYear: pm.card?.exp_year ?? null,
495	      },
496	    };
497	  } catch (e) {
498	    console.error(`[cards] could not record card from payment session for user ${userId}`, e);
499	    return { error: "We couldn't record the card from this payment." };
500	  }
501	}
502	
503	/**
504	 * Backstop for the closed-tab case.
505	 *
506	 * Checkout attaches the card to the Stripe customer BEFORE our `success_url` ever
507	 * runs. A customer who completes the Stripe page and then closes the tab has a
508	 * perfectly good card on file at Stripe and none on file here — and would be
509	 * dunned and suspended for it. This is the same class of bug as the Stripe
510	 * fulfilment incident: a browser redirect must never be the only trigger.
511	 *
512	 * Adoption is deliberately narrow. It requires a `card.setup_started` audit row
513	 * newer than any `card.removed` row and no older than a week, so a card the
514	 * customer explicitly REMOVED can never be silently resurrected and charged.
515	 */
516	export async function adoptUnclaimedCards(now = new Date()): Promise<number> {
517	  if (!stripeConfigured()) return 0;
518	  const since = new Date(now.getTime() - SETUP_INTENT_TTL_DAYS * 86400_000);
519	  const starts = await db.auditLog.findMany({
520	    where: { action: CARD_SETUP_STARTED, createdAt: { gt: since } },
521	    orderBy: { createdAt: "desc" },
522	    take: 200,
523	  });
524	  const userIds = [...new Set(starts.map((a) => a.userId).filter((v): v is string => !!v))];
525	  if (userIds.length === 0) return 0;
526	
527	  let adopted = 0;
528	  for (const userId of userIds) {
529	    const user = await db.user.findUnique({ where: { id: userId } });
530	    if (!user?.stripeCustomerId || user.stripePaymentMethodId) continue;
531	
532	    const startedAt = starts.find((a) => a.userId === userId)!.createdAt;
533	    const removed = await db.auditLog.findFirst({
534	      where: { userId, action: CARD_REMOVED },
535	      orderBy: { createdAt: "desc" },
536	    });
537	    if (removed && removed.createdAt > startedAt) continue; // removal is the later intent
538	
539	    try {
540	      const list = await stripe().paymentMethods.list({
541	        customer: user.stripeCustomerId,
542	        type: "card",
543	        limit: 5,
544	      });
545	      const pm = list.data[0]; // newest first
546	      if (!pm) continue;
547	      await persistCard(userId, user.stripeCustomerId, pm);
548	      await db.auditLog.create({
549	        data: {
550	          userId,
551	          action: "card.adopted",
552	          detail: `${cardDisplayLabel({
553	            brand: pm.card?.brand ?? null,
554	            last4: pm.card?.last4 ?? null,
555	            expMonth: pm.card?.exp_month ?? null,
556	            expYear: pm.card?.exp_year ?? null,
557	          })} (saved at Stripe but never confirmed in the browser)`,
558	        },
559	      });
560	      adopted++;
561	    } catch (e) {
562	      console.error(`[cards] could not adopt card for ${userId}`, e);
563	    }
564	  }
565	  return adopted;
566	}
