610	/**
611	 * A customer who saves a card mid-dunning has been told (by
612	 * `emails.paymentFailed`) that we'll "charge it straight away". Bringing the
613	 * scheduled retry forward is what makes that copy true — the next sweep picks it
614	 * up instead of waiting for the day-3 or day-5 slot. The failure COUNT is left
615	 * alone: the money is still owed.
616	 *
617	 * Clamped at each server's own `expiresAt` (never earlier) — found 2026-09-26 via
618	 * a real Stripe "same idempotency key, different parameters" error. A server can
619	 * be in dunning BEFORE its real due date (the admin "Renew now" button explicitly
620	 * allows charging early), so a plain `new Date()` here could land before that
621	 * server's `expiresAt`. `clearStaleDunning` (worker/billing.ts) reads a
622	 * `dunningNextAt` earlier than `expiresAt` as proof the dunning state belongs to
623	 * an already-settled OLDER period and wipes `dunningStage` back to 0 — for the
624	 * SAME still-open period. The very next attempt then rebuilds the idempotency key
625	 * an earlier attempt already used against the OLD card, which Stripe correctly
626	 * refuses to replay once the card differs. Never setting `dunningNextAt` earlier
627	 * than `expiresAt` removes the one input that made a live sequence look stale.
628	 */
629	export async function retryDunningNow(userId: string): Promise<number> {
630	  const servers = await db.server.findMany({
631	    where: { userId, dunningStage: { gt: 0 } },
632	    select: { id: true, expiresAt: true },
633	  });
634	  const now = new Date();
635	  await Promise.all(
636	    servers.map((s) =>
637	      db.server.update({
638	        where: { id: s.id },
639	        data: { dunningNextAt: s.expiresAt && s.expiresAt > now ? s.expiresAt : now },
640	      }),
641	    ),
642	  );
643	  return servers.length;
644	}
