650	type StripeErrorLike = {
651	  type?: string;
652	  rawType?: string;
653	  code?: string;
654	  decline_code?: string;
655	  message?: string;
656	  payment_intent?: { id?: string; status?: string };
657	};
658	
659	function asStripeError(e: unknown): StripeErrorLike | null {
660	  if (!e || typeof e !== "object") return null;
661	  const err = e as StripeErrorLike;
662	  return err.rawType || err.type?.startsWith("Stripe") ? err : null;
663	}
