665	export type OffSessionResult =
666	  /** Money captured. `amountCents` is what Stripe actually took, not what we asked for. */
667	  | { ok: true; paymentIntentId: string; amountCents: number; replayed: boolean }
668	  /** 3-D Secure or equivalent: the customer must approve it with their bank. */
669	  | { ok: false; kind: "requires_action"; paymentIntentId: string | null; message: string }
670	  /** The issuer said no. A real dunning event. */
671	  | { ok: false; kind: "declined"; message: string; code?: string }
672	  /** Our side or Stripe's side wobbled. NOT the customer's fault — never dun for it. */
673	  | { ok: false; kind: "transient"; message: string }
674	  /** Nothing to charge with (no card, Stripe off, amount under Stripe's floor). */
675	  | { ok: false; kind: "unavailable"; message: string };
