677	/**
678	 * Stable per-purpose marker written into PaymentIntent metadata.
679	 *
680	 * This is a SECOND idempotency guard that does not expire. Stripe's own
681	 * idempotency keys are only honoured for 24 hours, and our dunning schedule spans
682	 * six days, so the key alone cannot answer "have we already been paid for this
683	 * period?". Before charging we look for a live PaymentIntent carrying this marker
684	 * and reuse it — so a crash between "Stripe captured the money" and "we recorded
685	 * the payment intent id" can never turn into a second charge.
686	 */
687	export function renewalChargeMarker(serverId: string, periodStart: Date): string {
688	  return `renew:${serverId}:${periodStart.toISOString()}`;
689	}
690	
691	/** Marker for an automatic wallet top-up: at most one per account per day. */
692	export function autoRechargeMarker(userId: string, now: Date): string {
693	  return `autorecharge:${userId}:${now.toISOString().slice(0, 10)}`;
694	}
