696	/** Look for a charge we may already have made for this exact purpose. */
697	async function findChargeByMarker(
698	  customerId: string,
699	  marker: string,
700	): Promise<Stripe.PaymentIntent | null> {
701	  // Stripe's maximum page size, and it is the number that matters rather than a
702	  // comfortable-looking one. This lookup is the guard that DOES NOT EXPIRE, and it
703	  // is the only one covering the gap between a day-3 retry and the day-5 retry —
704	  // Stripe honours an idempotency key for just 24 hours while the dunning ladder
705	  // runs six days. It was 25 on the reasoning that "renewals are monthly", which
706	  // holds per server and not per CUSTOMER: this list is scoped to the customer, so
707	  // an account with thirty servers renewing in one sweep pushes the marker off the
708	  // first page and the permanent guard silently stops guarding — at which point a
709	  // crash between "Stripe captured" and "we recorded it" charges the card twice for
710	  // one period.
711	  const list = await stripe().paymentIntents.list({ customer: customerId, limit: 100 });
712	  const mine = list.data.filter((pi) => pi.metadata?.nxeonChargeKey === marker);
713	  return (
714	    mine.find((pi) => pi.status === "succeeded") ??
715	    mine.find((pi) => pi.status === "requires_action") ??
716	    mine.find((pi) => pi.status === "processing") ??
717	    null
718	  );
719	}
