721	/**
722	 * Charge the saved card off-session (no customer present).
723	 *
724	 * Two independent idempotency guards, because this moves real money on a timer
725	 * that retries:
726	 *  1. `marker` — pre-flight lookup of a live PaymentIntent for this exact purpose.
727	 *     Survives forever, catches the crash-after-capture window.
728	 *  2. `idempotencyKey` — Stripe replays the identical request instead of charging
729	 *     twice when two sweeps overlap. Only good for 24h, hence guard 1.
730	 */
731	export async function chargeSavedCardOffSession(opts: {
732	  user: CardUser;
733	  amountCents: number;
734	  description: string;
735	  marker: string;
736	  idempotencyKey: string;
737	  metadata?: Record<string, string>;
738	}): Promise<OffSessionResult> {
739	  const { user, amountCents, description, marker, idempotencyKey } = opts;
740	  if (!stripeConfigured()) return { ok: false, kind: "unavailable", message: "Stripe is not configured" };
741	  if (!user.stripeCustomerId || !user.stripePaymentMethodId) {
742	    return { ok: false, kind: "unavailable", message: "No saved card" };
743	  }
744	  // `walletSplit` already keeps the card leg at or above Stripe's floor; this is
745	  // the belt-and-braces check so a future caller can't send a rejectable amount.
746	  if (amountCents < STRIPE_MIN_CENTS) {
747	    return { ok: false, kind: "unavailable", message: `Below Stripe minimum (${STRIPE_MIN_CENTS}c)` };
748	  }
749	
750	  // Guard 1: did we already charge for this purpose?
751	  try {
752	    const existing = await findChargeByMarker(user.stripeCustomerId, marker);
753	    if (existing?.status === "succeeded") {
754	      return {
755	        ok: true,
756	        paymentIntentId: existing.id,
757	        amountCents: existing.amount_received || existing.amount,
758	        replayed: true,
759	      };
760	    }
761	    if (existing?.status === "requires_action") {
762	      // A 3-D Secure wall does not move: retrying the SAME card off-session hits it
763	      // again, so reuse the existing intent (and its link) rather than piling up a
764	      // new challenge every retry. A DIFFERENT card is a different story — if the
765	      // customer has since saved one, cancel the stale challenge and really try it,
766	      // otherwise saving a new card would silently change nothing.
767	      const pendingPm =
768	        typeof existing.payment_method === "string"
769	          ? existing.payment_method
770	          : (existing.payment_method?.id ?? null);
771	      if (pendingPm === user.stripePaymentMethodId) {
772	        return {
773	          ok: false,
774	          kind: "requires_action",
775	          paymentIntentId: existing.id,
776	          message: "Awaiting bank confirmation",
777	        };
778	      }
779	      await cancelIfUnconfirmed(existing.id);
780	    }
781	    if (existing?.status === "processing") {
782	      return { ok: false, kind: "transient", message: "A charge for this period is still settling" };
783	    }
784	  } catch (e) {
785	    // A failed lookup must not become a blind second charge.
786	    console.error("[cards] pre-flight charge lookup failed", e);
787	    return { ok: false, kind: "transient", message: "Could not verify existing charges" };
788	  }
789	
790	  try {
791	    const pi = await stripe().paymentIntents.create(
792	      {
793	        amount: amountCents,
794	        currency: "usd",
795	        customer: user.stripeCustomerId,
796	        payment_method: user.stripePaymentMethodId,
797	        confirm: true,
798	        off_session: true,
799	        // No browser exists here, so a redirect-based next_action could never be
800	        // satisfied — and asking for one is what makes Stripe demand a return_url.
801	        automatic_payment_methods: { enabled: true, allow_redirects: "never" },
802	        description,
803	        metadata: { ...(opts.metadata ?? {}), nxeonUserId: user.id, nxeonChargeKey: marker },
804	      },
805	      { idempotencyKey },
806	    );
807	    if (pi.status === "succeeded") {
808	      return { ok: true, paymentIntentId: pi.id, amountCents: pi.amount_received || pi.amount, replayed: false };
809	    }
810	    if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
811	      return { ok: false, kind: "requires_action", paymentIntentId: pi.id, message: "Bank confirmation required" };
812	    }
813	    if (pi.status === "processing") {
814	      return { ok: false, kind: "transient", message: "Payment is still processing" };
815	    }
816	    return { ok: false, kind: "declined", message: `Payment could not be completed (${pi.status})` };
817	  } catch (e) {
818	    return classifyChargeError(e);
819	  }
820	}
