822	/**
823	 * Split a charge failure into the three cases that deserve different treatment:
824	 * the bank wants the customer to confirm, the bank said no, or nothing about the
825	 * customer went wrong at all.
826	 *
827	 * The default is `transient` on purpose. A misclassified transient error costs us
828	 * a delayed renewal; a misclassified decline costs a paid-up customer their
829	 * server. Unknown always resolves to the direction that cannot suspend anyone.
830	 */
831	function classifyChargeError(e: unknown): OffSessionResult {
832	  const err = asStripeError(e);
833	  const message = String(err?.message ?? (e as Error)?.message ?? e).slice(0, 300);
834	  if (!err) return { ok: false, kind: "transient", message };
835	
836	  // 3-D Secure surfaces as a card error with this code, with the PI attached.
837	  if (err.code === "authentication_required" || err.payment_intent?.status === "requires_action") {
838	    return {
839	      ok: false,
840	      kind: "requires_action",
841	      paymentIntentId: err.payment_intent?.id ?? null,
842	      message,
843	    };
844	  }
845	  if (err.rawType === "card_error") {
846	    return { ok: false, kind: "declined", message, code: err.decline_code ?? err.code };
847	  }
848	  // The saved method vanished at Stripe (detached elsewhere, customer deleted).
849	  // Not a decline — there is nothing to retry until a new card is saved.
850	  if (err.rawType === "invalid_request_error" && err.code === "resource_missing") {
851	    return { ok: false, kind: "unavailable", message };
852	  }
853	  return { ok: false, kind: "transient", message };
854	}
