38	const ENV_GRACE_DAYS = Number(process.env.NXEON_GRACE_DAYS ?? 3);
39	const ENV_TERMINATE_DAYS = process.env.NXEON_TERMINATE_DAYS
40	  ? ENV_GRACE_DAYS + Number(process.env.NXEON_TERMINATE_DAYS)
41	  : 14;
42	const ENV_WARN_DAYS = process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS
43	  ? ENV_TERMINATE_DAYS - Number(process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS)
44	  : 7;
45	
46	export async function dunningConfig(): Promise<DunningConfig> {
47	  const graceDays = Math.max(0, await getSettingInt("dunning_grace_days", ENV_GRACE_DAYS));
48	  let terminateDays = await getSettingInt("dunning_terminate_days", ENV_TERMINATE_DAYS);
49	  let warnDays = await getSettingInt("dunning_warn_days", ENV_WARN_DAYS);
50	  const autoSuspend = await getSettingBool("auto_suspend_enabled", true);
51	
52	  // Clamp. These are free-text number fields in an admin panel and the action they
53	  // gate is irreversible — a typo (or a 0) must never be able to destroy a VM on the
54	  // same day it is suspended, or before the dunning sequence has even finished. The
55	  // floor includes the slip cap because a card sequence that started late can push
56	  // the suspension itself out to CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS, and
57	  // termination must always land AFTER the suspension it follows.
58	  const latestSuspendDay = Math.max(graceDays, CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS);
59	  terminateDays = Math.max(terminateDays, latestSuspendDay + 1);
60	  warnDays = Math.min(Math.max(warnDays, 1), terminateDays - 1);
61	  return { graceDays, warnDays, terminateDays, autoSuspend };
