203	/** The renewal queue, and the row shape every card/dunning helper below works on. */
204	async function dueServers(now: Date) {
205	  return db.server.findMany({
206	    where: {
207	      isFree: false,
208	      expiresAt: { lt: now },
209	      status: { in: ["RUNNING", "STOPPED"] },
210	    },
211	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
