216	/**
217	 * Subscription sweep, run periodically by the worker:
218	 *  - expired + autoRenew, wallet covers it     -> charge wallet, extend the term
219	 *  - expired + autoRenew, wallet falls short   -> apply the credit, auto-charge the
220	 *                                                 saved card for the remainder
221	 *  - card declined                             -> dunning (retry days 1/3/5 + email)
222	 *  - retries exhausted, or no card past grace  -> queue SUSPEND with unpaid note
223	 * Free servers (isFree) are never touched.
224	 */
225	export async function billingSweep() {
226	  const now = new Date();
227	  const cfg = await dunningConfig();
228	  const prices = {
229	    ipMonthlyCents: await dedicatedIpMonthlyCents(), // admin setting; 0 = included
230	    // Per-GB/month price for extra ROOT DISK. Read once per sweep; every server that
231	    // bought extra storage renews at plan + (extraDiskGB x this) x months, so the
232	    // upsell keeps billing every cycle rather than being a one-off charge.
233	    extraDiskPerGbCents: await extraDiskPerGbCents(),
234	    // Monthly price of the Plus backup-retention tier. A server on Plus renews at
235	    // plan + this x months, folded into totalCents by renewalCharge exactly like
236	    // the extra-disk line, so the retention upsell keeps billing every cycle.
237	    backupPlusCents: await backupPlusMonthlyCents(),
238	    // The admin ANNUAL discount. A 12-month server renews at this rate — the same
239	    // one it was ordered and displayed at — so an annual subscription renews for
240	    // another year at the SAME annual price. Ignored for every other term.
241	    annualDiscountPct: await annualDiscountPct(),
242	  };
243	  // Seller country + global fallback rate, read ONCE per sweep. The per-server VAT
244	  // rate is resolved (purely) from each owner's billing country against these, so the
245	  // renewal charge, the card leg and the invoice all carry the same tax the customer
246	  // is shown elsewhere (Finding 1).
247	  const taxParams = { sellerCountry: await sellerCountry(), fallbackPercent: await taxRate() };
248	  // Off by default — see the setting's own doc comment in lib/settings.ts.
249	  const paypalFallbackEnabled = await getSettingBool("renewals_paypal_fallback_enabled", false);
250	  const taxCtxFor = (u: { billingCountry?: string | null; vatId?: string | null }): TaxContext =>
251	    resolveCountryTaxRate({
252	      country: u.billingCountry ?? null,
253	      vatId: u.vatId ?? null,
254	      sellerCountry: taxParams.sellerCountry,
255	      fallbackPercent: taxParams.fallbackPercent,
256	    });
257	
258	  // Claim any card that was saved at Stripe but never confirmed in the browser,
259	  // BEFORE the renewal queries read card state — otherwise a customer who closed
260	  // the tab on Stripe's page gets dunned for a card we simply failed to record.
261	  try {
262	    const adopted = await adoptUnclaimedCards(now);
263	    if (adopted > 0) console.log(`[billing] adopted ${adopted} unconfirmed saved card(s)`);
264	  } catch (e) {
265	    console.error("[billing] card adoption error", e);
266	  }
267	
268	  // Renewal warnings: notify once when a paid server is within 3 days of expiry
269	  const soon = new Date(now.getTime() + 3 * 86400_000);
270	  const upcoming = await db.server.findMany({
271	    where: {
272	      isFree: false,
273	      expiresAt: { gt: now, lt: soon },
274	      status: { in: ["RUNNING", "STOPPED"] },
275	    },
276	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
277	  });
278	  for (const server of upcoming) {
279	    // Tax-inclusive so the "renewal is $X" warning matches what the sweep will take.
280	    // Partner discount folded in too (Creator Partner Program) so a partner-
281	    // attached customer's warning shows the real 10%-off amount, not the list price.
282	    const partnerPct = (await partnerDiscountForRenewal(server.userId)).percent;
283	    const warnCents = renewalCharge(server, {
284	      ...prices,
285	      taxRatePercent: taxCtxFor(server.user).ratePercent,
286	      partnerDiscountPercent: partnerPct,
287	    }).totalCents;
288	    // A customer with a card (or, when enabled, a vaulted PayPal method) on
289	    // file needs no warning and no top-up: the renewal applies their wallet
290	    // credit and auto-charges the remainder. Telling them to "top up to avoid
291	    // suspension" would raise an alarm about a suspension that is not going
292	    // to happen.
293	    if (server.autoRenew && (server.user.balanceCents >= warnCents || hasChargeableRenewalMethod(server.user, paypalFallbackEnabled))) {
294	      continue;
295	    }
296	    const already = await db.notification.findFirst({
297	      where: {
298	        userId: server.userId,
299	        title: { contains: server.hostname },
300	        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
301	        AND: { title: { contains: "renews soon" } },
302	      },
303	    });
304	    if (!already) {
305	      await db.notification.create({
306	        data: {
307	          userId: server.userId,
308	          title: `${server.hostname} renews soon — action needed`,
309	          body: server.autoRenew
310	            ? `Renewal is $${(warnCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
311	            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
312	          href: `/dashboard/servers/${server.id}`,
313	        },
314	      });
315	    }
316	  }
317	  const due = await dueServers(now);
318	
319	  for (const server of due) {
320	    // One unhappy server must never abort the queue behind it. Every money write
321	    // below is individually guarded (CAS on expiresAt, UNIQUE on the payment intent
322	    // id, Stripe idempotency key), so continuing past a failure can only ever cost a
323	    // delayed renewal — never a duplicate charge. Without this, a single row with a
324	    // wedged Stripe customer would leave every later customer unrenewed AND
325	    // eventually suspended, for a fault that was entirely ours.
326	    try {
327	      await renewDueServer(server, { now, cfg, prices, taxParams, paypalFallbackEnabled });
328	    } catch (e) {
329	      console.error(`[billing] renewal pass failed for ${server.hostname}`, e);
330	    }
331	  }
332	
333	  await terminateOverdue(now, cfg, prices, taxParams);
334	  await reapAbandonedSuspended(now, cfg);
335	
336	  // Card housekeeping: nudge before a saved card expires, and honour the customer's
337	  // own automatic top-up preference. Both are isolated so a Stripe or SMTP problem
338	  // can never take the renewal sweep down with it.
339	  try {
340	    await cardExpirySweep(now);
341	  } catch (e) {
342	    console.error("[billing] card-expiry sweep error", e);
343	  }
344	  try {
345	    await autoRechargeSweep(now);
346	  } catch (e) {
347	    console.error("[billing] auto-recharge sweep error", e);
348	  }
349	
350	  await domainAutoRenewSweep(now);
351	
352	  // Poll in-flight inbound transfers on the same cadence as domain renewals —
353	  // domain upkeep all lives on one timer.
354	  try {
355	    await domainTransferInSweep(now);
356	  } catch (e) {
357	    console.error("[billing] domain transfer-in sweep error", e);
358	  }
359	}
