361	/**
362	 * One expired server: renew it from wallet + card, or move it along the dunning
363	 * sequence, or suspend it once every promised attempt is spent.
364	 */
365	async function renewDueServer(
366	  server: DueServer,
367	  ctx: {
368	    now: Date;
369	    cfg: DunningConfig;
370	    prices: { ipMonthlyCents: number; extraDiskPerGbCents: number; backupPlusCents: number; annualDiscountPct: number };
371	    taxParams: { sellerCountry: string; fallbackPercent: number };
372	    paypalFallbackEnabled: boolean;
373	  },
374	) {
375	  const { now, cfg, taxParams, paypalFallbackEnabled } = ctx;
376	  // Resolve the owner's VAT/GST from their billing country (Finding 1) and fold it
377	  // into the renewal price so the wallet debit, any card leg and the invoice all
378	  // agree. Default rate 0 (no country on file) leaves this identical to before.
379	  const taxCtx = resolveCountryTaxRate({
380	    country: server.user.billingCountry ?? null,
381	    vatId: server.user.vatId ?? null,
382	    sellerCountry: taxParams.sellerCountry,
383	    fallbackPercent: taxParams.fallbackPercent,
384	  });
385	  // Creator Partner Program: 10% off every renewal, forever, once attached to an
386	  // ACTIVE partner (0 for the overwhelming majority of servers). See
387	  // lib/partner-pricing.ts and lib/renewal-charge.ts's own doc comment.
388	  const partnerPct = (await partnerDiscountForRenewal(server.userId)).percent;
389	  const prices = { ...ctx.prices, taxRatePercent: taxCtx.ratePercent, partnerDiscountPercent: partnerPct };
390	  const charge = renewalCharge(server, prices);
391	  const renewCents = charge.totalCents;
392	  const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
393	  const newExpiry = addMonths(base, charge.months);
394	
395	  await clearStaleDunning(server);
396	
397	  let renewed = false;
398	  if (server.autoRenew) {
399	    // `server.user.balanceCents` came from a snapshot taken before this loop and
400	    // is stale as soon as the first renewal in this pass debits a wallet, so the
401	    // SPLIT is computed from a fresh read. It is still never a gate: `debitWallet`
402	    // re-checks funds atomically and the compare-and-swap on `expiresAt` stops a
403	    // concurrent renewNow()/second pass charging the same period twice.
404	    const fresh = await db.user.findUnique({
405	      where: { id: server.userId },
406	      select: { balanceCents: true },
407	    });
408	    const split = walletSplit({
409	      dueCents: renewCents,
410	      balanceCents: fresh?.balanceCents ?? 0,
411	      useWallet: true,
412	    });
413	    const cardInPlay = hasChargeableCard(server.user);
414	    const paypalInPlay = !cardInPlay && paypalFallbackEnabled && hasChargeablePayPal(server.user);
415	
416	    if (split.cardCents === 0) {
417	      // Wallet covers the whole renewal — no card involved, no Stripe call.
418	      const outcome = await commitRenewal({ server, charge, newExpiry, taxCountry: taxCtx.country });
419	      renewed = outcome !== "insufficient";
420	      if (outcome === "renewed") {
421	        console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
422	      }
423	    } else if (cardInPlay) {
424	      // Only attempt on the scheduled day. Without this gate a 10-minute sweep
425	      // would burn all three retries — and send all three emails — within half an
426	      // hour of the first decline.
427	      //
428	      // A scheduled time, once set, ALWAYS wins over the attempt counter, which buys
429	      // two things. `retryDunningNow` (fired when a customer saves a new card
430	      // mid-dunning) gets a real attempt even at the exhausted stage — refusing there
431	      // would suspend a customer whose brand-new card we never once tried. And the
432	      // exhausted stage's schedule points at the suspension day itself, so every
433	      // server gets one final, silent try at the card in the same pass that pauses it.
434	      const dueForRetry = server.dunningNextAt
435	        ? now >= server.dunningNextAt
436	        : server.dunningStage < DUNNING_EXHAUSTED;
437	      if (dueForRetry) {
438	        renewed = (
439	          await attemptCardRenewal({
440	            server,
441	            charge,
442	            cardCents: split.cardCents,
443	            newExpiry,
444	            now,
445	            cfg,
446	            taxCountry: taxCtx.country,
447	          })
448	        ).renewed;
449	      }
450	    } else if (paypalInPlay) {
451	      // Same scheduled-retry gate as the card path above — a PayPal-funded
452	      // customer gets the exact same dunning cadence, not an immediate try
453	      // every 10-minute sweep tick.
454	      const dueForRetry = server.dunningNextAt
455	        ? now >= server.dunningNextAt
456	        : server.dunningStage < DUNNING_EXHAUSTED;
457	      if (dueForRetry) {
458	        renewed = await attemptPayPalRenewal({
459	          server,
460	          charge,
461	          cardCents: split.cardCents,
462	          newExpiry,
463	          now,
464	          cfg,
465	          taxCountry: taxCtx.country,
466	        });
467	      }
468	    } else {
469	      console.log(
470	        `[billing] ${server.hostname} short by ${fmtUsd(split.cardCents)} and no card on file — grace/suspend applies`,
471	      );
472	    }
473	  }
474	
475	  if (renewed) {
476	    // nothing further this pass
477	  } else {
478	    const suspendAt = suspendDueAt(server, hasChargeableCard(server.user), cfg);
479	    if (suspendAt && now >= suspendAt) {
480	      await suspendUnpaid(server, cfg);
481	    }
482	  }
483	}
