485	/**
486	 * ADMIN-TRIGGERED IMMEDIATE RENEWAL for one server — same money mechanics as
487	 * `renewDueServer` above (wallet first, the saved card for the remainder, via
488	 * the exact same `walletSplit` / `hasChargeableCard` / `attemptCardRenewal` /
489	 * `commitRenewal` calls that sweep makes), deliberately NOT `renewDueServer`
490	 * itself. Two real differences justify a separate entry point rather than
491	 * reusing it directly:
492	 *
493	 *  1. `renewDueServer` only ever attempts a charge when `server.autoRenew` is
494	 *     true — correct for the unattended sweep (autoRenew is the customer's
495	 *     opt-in to being charged with nobody watching), but an admin clicking
496	 *     "Renew now" for a specific customer is an attributable, one-off
497	 *     decision, exactly like the customer's OWN `renewNow` in lib/actions.ts,
498	 *     which has never gated on autoRenew either. Gating this path on it too
499	 *     would silently no-op for every customer who has turned auto-renew off
500	 *     — likely a large share of the accounts an admin would reach for this.
501	 *  2. `renewDueServer` returns void and only ever logs to the console — fine
502	 *     for a background sweep nobody is watching, but useless for an admin
503	 *     action that has to tell a human what happened. `attemptCardRenewal`'s
504	 *     richer `CardRenewalOutcome` (broadened for this exact purpose — see its
505	 *     own doc comment) is threaded straight through instead of being
506	 *     collapsed back to a bare boolean the way `renewDueServer` uses it.
507	 *
508	 * Deliberately UNCHANGED from `renewDueServer`: the dunning-retry schedule
509	 * gate (`dueForRetry`) is skipped on purpose too — an admin clicking the
510	 * button IS the attempt, not a scheduled retry, so there is nothing to wait
511	 * for and nothing to burn early. `clearStaleDunning`, `walletSplit`,
512	 * `hasChargeableCard`, `attemptCardRenewal` and `commitRenewal` are the exact
513	 * same calls `renewDueServer` makes; this function only changes WHETHER and
514	 * WHEN they run, never HOW they charge — there is still exactly one renewal
515	 * formula and one wallet/card split.
516	 *
517	 * Does not require `server.expiresAt` to already have passed — an admin may
518	 * legitimately renew a little early (see the call site, `adminRenewServerNow`
519	 * in lib/actions.ts). `commitRenewal`'s own `Math.max(expiresAt, now)` base
520	 * and its CAS on the exact `expiresAt` read here make an early renewal exactly
521	 * as safe as a concurrent late one: two overlapping attempts (an admin
522	 * double-click, or an admin click racing the automatic sweep) can only ever
523	 * result in ONE of them actually charging and advancing the period — the
524	 * loser reports `alreadyRenewed`, never a second charge.
525	 */
526	export type ImmediateRenewalResult =
527	  | {
528	      ok: true;
529	      /** Which rail(s) actually paid this renewal. */

980	export type CardRenewalOutcome =
981	  | { renewed: true; amountCents: number; replayed: boolean }
982	  | {
983	      renewed: false;
984	      /** Why no charge landed. `walletDebitRaced` is not a decline at all — see below. */
985	      kind: "transient" | "unavailable" | "requiresAction" | "declined" | "walletDebitRaced";
986	      message: string;
987	      /** Present only for `kind: "declined"` — the issuer's own decline code, when Stripe supplied one. */
988	      code?: string;
989	    };
