991	async function attemptCardRenewal(opts: {
992	  server: DueServer;
993	  charge: RenewalCharge;
994	  cardCents: number;
995	  newExpiry: Date;
996	  now: Date;
997	  cfg: DunningConfig;
998	  /** Destination country the VAT was charged for; passed through to the invoice. */
999	  taxCountry?: string;
1000	}): Promise<CardRenewalOutcome> {
1001	  const { server, charge, cardCents, newExpiry, now, cfg, taxCountry } = opts;
1002	  const user = server.user;
1003	  const periodStart = server.expiresAt!;
1004	  const marker = renewalChargeMarker(server.id, periodStart);
1005	  const idempotencyKey = `nxeon_renew_${server.id}_${periodStart.getTime()}_a${server.dunningStage}_${cardCents}`;
1006	  const cardLabel = savedCardLabel(user) ?? "your saved card";
1007	
1008	  const result = await chargeSavedCardOffSession({
1009	    user,
1010	    amountCents: cardCents,
1011	    description: `Renewal: ${charge.label} (${server.hostname})`,
1012	    marker,
1013	    idempotencyKey,
1014	    metadata: {
1015	      nxeonServerId: server.id,
1016	      nxeonPeriodStart: periodStart.toISOString(),
1017	      nxeonKind: "renewal",
1018	    },
1019	  });
1020	
1021	  if (result.ok) {
1022	    // Exactly what Stripe took, not what we asked for — a replayed intent can carry
1023	    // an older amount and the ledger must match the bank, not our intent.
1024	    const credited = await creditOffSessionCharge({
1025	      userId: server.userId,
1026	      amountCents: result.amountCents,
1027	      description: `Card payment for ${server.hostname} renewal (${cardLabel})`,
1028	      paymentIntentId: result.paymentIntentId,
1029	      // No invoice for the card leg: `commitRenewal` issues ONE paid invoice for
1030	      // the whole renewal, and a second document for the card portion would
1031	      // double-count the same revenue.
1032	    });
1033	    const outcome = await commitRenewal({ server, charge, newExpiry, taxCountry });
1034	
1035	    // The receipt is tied to the CREDIT, not the renewal: `creditOffSessionCharge`
1036	    // returns false on the P2002 that means "already credited", so a replayed
1037	    // capture cannot email the same customer a second receipt for one charge.
1038	    if (credited) {
1039	      await mail(
1040	        user.email,
1041	        user.id,
1042	        emails.paymentReceipt(
1043	          fmtUsd(result.amountCents),
1044	          `${charge.label} — ${server.hostname}`,
1045	          user.cardLast4 ?? "",
1046	        ),
1047	        // ACCOUNT tier — a receipt is the one mail from this sweep a customer may
1048	        // legitimately opt out of. Everything else here is CRITICAL by default.
1049	        "receipt",
1050	      );
1051	    }
1052	
1053	    if (outcome === "insufficient") {
1054	      // The card paid, the wallet was credited, and the debit STILL failed — the
1055	      // customer spent the credit between our split read and the transaction. The
1056	      // money is not lost, it is sitting in their wallet; re-run shortly rather
1057	      // than charging again (the marker replays this same capture, so the next
1058	      // pass cannot take a second payment) and do NOT count it as a dunning
1059	      // failure, because nothing about their card went wrong.
1060	      console.error(
1061	        `[billing] ${server.hostname}: card captured ${fmtUsd(result.amountCents)} but the wallet debit fell short — retrying shortly`,
