function code(relative: string): string {
  return stripComments(readFileSync(new URL(relative, import.meta.url), "utf8"));
}

/**
 * One function's text, from its declaration to the next top-level
 * declaration — same slicer money-core-guards.test.ts and
 * retention-offer.test.ts use, copied rather than imported so this file has
 * no import that could pull in a "use server"/db-touching module transitively.
 */
function fn(src: string, declaration: string): string {
  const start = src.indexOf(declaration);
  assert.notEqual(start, -1, `${declaration} not found — has it moved or been renamed?`);
  const rest = src.slice(start + declaration.length);
  const next = rest.search(/\nexport (async )?(function|const|type|class)/);
  const body = next === -1 ? rest : rest.slice(0, next);
  assert.ok(body.length > 0, `${declaration} produced an empty body`);
  return body;
}

