// Stripe TEST-mode reproduction of the live renewal failure.
// Refuses to run with anything but an sk_test_ key.
import Stripe from "/opt/nxeon/node_modules/stripe/cjs/stripe.cjs.node.js";

const key = process.env.STRIPE_SECRET_KEY ?? "";
if (!key.startsWith("sk_test_")) {
  console.error("refusing: STRIPE_SECRET_KEY is not a TEST key");
  process.exit(2);
}
const stripe = new Stripe(key);
const tag = `billfix-repro-${Date.now()}`;

async function freshPm() {
  return stripe.paymentMethods.create({ type: "card", card: { token: "tok_visa" } });
}
async function offSession(customer, pm, label) {
  try {
    const pi = await stripe.paymentIntents.create({
      amount: 620, currency: "usd", customer, payment_method: pm, confirm: true, off_session: true,
      automatic_payment_methods: { enabled: true, allow_redirects: "never" },
      description: `${tag} ${label}`,
    });
    console.log(`  [${label}] off-session OK status=${pi.status}`);
    return pi;
  } catch (e) {
    console.log(`  [${label}] off-session FAILED type=${e.type} rawType=${e.rawType} code=${e.code} decline=${e.decline_code}`);
    console.log(`     message: ${e.message}`);
    return null;
  }
}

const customer = await stripe.customers.create({ email: `${tag}@example.test`, metadata: { nxeonTest: tag } });
console.log("customer", customer.id);

// CASE A — PM consumed by a PI with NO customer (guest checkout), then reused.
{
  const pm = await freshPm();
  const pi = await stripe.paymentIntents.create({
    amount: 899, currency: "usd", payment_method: pm.id, confirm: true,
    automatic_payment_methods: { enabled: true, allow_redirects: "never" }, description: `${tag} A-guest`,
  });
  const after = await stripe.paymentMethods.retrieve(pm.id);
  console.log(`A: guest PI ${pi.status}; pm.customer after = ${after.customer}`);
  await offSession(customer.id, pm.id, "A reuse");
  try { await stripe.paymentMethods.attach(pm.id, { customer: customer.id }); console.log("  A attach OK (unexpected)"); }
  catch (e) { console.log(`  A attach FAILED code=${e.code}: ${e.message.slice(0, 120)}`); }
}

// CASE B — PM used on a PI WITH customer but WITHOUT setup_future_usage (our outstanding-balance checkout shape), then reused.
{
  const pm = await freshPm();
  const pi = await stripe.paymentIntents.create({
    amount: 899, currency: "usd", customer: customer.id, payment_method: pm.id, confirm: true,
    automatic_payment_methods: { enabled: true, allow_redirects: "never" }, description: `${tag} B-cust-no-sfu`,
  });
  const after = await stripe.paymentMethods.retrieve(pm.id);
  console.log(`B: PI ${pi.status}; pm.customer after = ${after.customer}`);
  await offSession(customer.id, pm.id, "B reuse");
}

// CASE C — PM used WITH customer AND setup_future_usage=off_session (the fixed shape), then reused off-session.
{
  const pm = await freshPm();
  const pi = await stripe.paymentIntents.create({
    amount: 899, currency: "usd", customer: customer.id, payment_method: pm.id, confirm: true, setup_future_usage: "off_session",
    automatic_payment_methods: { enabled: true, allow_redirects: "never" }, description: `${tag} C-cust-sfu`,
  });
  const after = await stripe.paymentMethods.retrieve(pm.id);
  console.log(`C: PI ${pi.status}; pm.customer after = ${after.customer}`);
  await offSession(customer.id, pm.id, "C reuse");
}

// CASE D — attached then DETACHED (customer removed the card), then reused.
{
  const pm = await freshPm();
  await stripe.paymentMethods.attach(pm.id, { customer: customer.id });
  await stripe.paymentMethods.detach(pm.id);
  const after = await stripe.paymentMethods.retrieve(pm.id);
  console.log(`D: detached; pm.customer after = ${after.customer}`);
  await offSession(customer.id, pm.id, "D reuse");
}

// CASE E — SCA-required test card, attached, charged off-session.
{
  const pm = await stripe.paymentMethods.create({ type: "card", card: { token: "tok_threeDSecure2Required" } });
  await stripe.paymentMethods.attach(pm.id, { customer: customer.id });
  await offSession(customer.id, pm.id, "E sca");
}

// CASE F — attached card that declines (insufficient funds).
{
  const pm = await stripe.paymentMethods.create({ type: "card", card: { token: "tok_chargeDeclinedInsufficientFunds" } });
  await stripe.paymentMethods.attach(pm.id, { customer: customer.id });
  await offSession(customer.id, pm.id, "F decline");
}

await stripe.customers.del(customer.id);
console.log("cleaned up test customer");

