function build(opts: {
  template: string;
  subject: string;
  preheader: string;
  eyebrow?: string;
  accent?: Accent;
  heading: string;
  blocks: string[];
  cta?: { href: string; label: string; accent?: Accent };
  note?: string;
}): BuiltEmail {
