input.new_string:
      cta: { href: billingUrl, label: "Update card", accent: "warn" },
      note: "We only charge the card for renewals you've already agreed to, and only for the amount your wallet credit doesn't cover.",
    }),

  /**
   * The saved card can never be charged again at Stripe — OUR fault (it was
   * recorded in a way Stripe does not allow to be reused), not a decline. Three
   * rungs of one ladder (worker/billing.ts nudgeCardReadd): the first notice on
   * detection, reminders on day 1 and 3, and a final notice a day before the
   * platform grace runs out. Honest wording — the customer did nothing wrong, the
   * server is NOT suspended, and the one action that fixes it is "add the card
   * again". `graceEndFormatted` is the real `Server.billingGraceUntil`, never a
   * guess. The CTA is the Billing page, where "Add a card" opens the setup flow.
   */
  cardReaddRequired: (
    hostname: string,
    amountFormatted: string,
    cardLabelText: string,
    graceEndFormatted: string,
    billingUrl: string,
    stage: "first" | "reminder" | "final" = "first",
  ): BuiltEmail => {
    const common = [
      stillRunning(hostname, `It stays running until at least <b>${graceEndFormatted}</b> while you sort this out.`),
      emailPanel(
        emailKeyValue([
          ["Server", hostname],
          ["Renewal due", amountFormatted],
          ["Card on file", cardLabelText || "Saved card"],
          ["Running until at least", graceEndFormatted],
        ]),
        stage === "final" ? "danger" : "warn",
      ),
    ];
    if (stage === "first") {
      return build({
        template: "card_readd_required",
        subject: `Action needed: re-add your card for ${hostname}`,
        preheader: `${hostname} is still running. We need you to add your card again — nothing is wrong with the card itself.`,
        eyebrow: "Action needed",
        accent: "warn",
        heading: "Please add your card again",
        blocks: [
          emailParagraph(
            `We tried to renew <b>${hostname}</b> on your saved card, but the way that card was stored on our side means our payment processor won't let us charge it again. This is a problem on our end — <b>not a decline, and not anything you did</b>. We're sorry about that.`,
          ),
          ...common,
          emailParagraph(
            `Adding the card again (the same card is fine) takes about a minute, and the renewal will go through automatically on the next check — no need to pay anything by hand.`,
          ),
        ],
        cta: { href: billingUrl, label: "Re-add my card", accent: "warn" },
        note: "If you'd rather pay this renewal another way, your Billing page also lets you top up your balance or pay by PayPal. Reply to this email if anything is unclear and we'll help.",
      });
    }
    if (stage === "reminder") {
      return build({
        template: "card_readd_reminder",
        subject: `Reminder: ${hostname} still needs a card for its renewal`,
        preheader: `${hostname} is still running. Add your card again and the renewal completes automatically.`,
        eyebrow: "Reminder",
        accent: "warn",
        heading: "Your card still needs re-adding",
        blocks: [
          emailParagraph(
            `A quick reminder that the renewal for <b>${hostname}</b> is waiting on a card we can actually charge. The card we have on file can't be reused on our side, so it needs to be added again — the same card is fine.`,
          ),
          ...common,
          emailParagraph("Once a card is added we'll charge the renewal automatically within the hour and send you a receipt."),
        ],
        cta: { href: billingUrl, label: "Re-add my card", accent: "warn" },
        note: "Already added a card? Then there's nothing more to do — this reminder and the renewal may have crossed. Reply to this email if you'd like us to check.",
      });
    }
    return build({
      template: "card_readd_final_notice",
      subject: `Final reminder: add a card for ${hostname} by ${graceEndFormatted}`,
      preheader: `${hostname} is still running, but it will pause on ${graceEndFormatted} unless a card is added.`,
      eyebrow: "Final reminder",
      accent: "danger",
      heading: "Last reminder before this server pauses",
      blocks: [
        emailParagraph(
          `We've held <b>${hostname}</b> open while waiting for a card we can charge for its renewal, and that extra time runs out on <b>${graceEndFormatted}</b>. After that the server pauses — nothing is deleted, your data and configuration stay exactly as they are, and adding a card brings it straight back.`,
        ),
        ...common,
        emailParagraph("Adding the card again (or topping up your balance) before then avoids the pause entirely."),
      ],
      cta: { href: billingUrl, label: "Re-add my card now", accent: "danger" },
      note: "Need a few more days? Reply to this email before the date above — we'd much rather extend it than pause anything.",
    });
  },
};

