/**
 * The "re-add your card" ladder, run only while `Server.billingGraceUntil` is in
 * the future and the account has no chargeable card. Reuses the dunning
 * columns (free in this state: the decline ladder needs a card) — `dunningStage`
 * is the rung reached, `dunningNextAt` gates the next one:
 *
 *   rung 1  first notice   — sent by `retireUnusableCard` the moment the dead card is found
 *   rung 2  reminder       — CARD_READD_REMINDER_DAYS[0] (day 1) after the first notice
 *   rung 3  reminder       — CARD_READD_REMINDER_DAYS[1] (day 3)
 *   rung 4  final notice   — one day before `billingGraceUntil`, then nothing more
 *
 * Every rung reschedules at least MIN_RETRY_GAP_MS out, so a worker that was down
 * cannot fire the whole ladder in one afternoon. The customer saving a card ends
 * it: `hasChargeableCard` turns true, the normal card path runs, and
 * `commitRenewal` clears the grace and the stage together.
 */
async function nudgeCardReadd(opts: { server: DueServer; cardCents: number; now: Date }): Promise<void> {
  const { server, cardCents, now } = opts;
  const graceUntil = server.billingGraceUntil!;
  if (server.dunningNextAt && now < server.dunningNextAt) return; // not this rung's turn yet
  const finalAt = new Date(graceUntil.getTime() - DAY);
  const rung = server.dunningStage;
  // Rung 0 here means the grace was granted by an ADMIN (not by card retirement),
  // so the first notice has not gone out yet — send it now as rung 1.
  if (rung === 0) {
    await sendCardReaddNotice(server, cardCents, "first", now);
    return;
  }
  if (rung <= CARD_READD_REMINDER_DAYS.length) {
    // A reminder rung — unless the final notice is already due, in which case
    // skip straight to it rather than stacking two emails on one day.
    if (now >= finalAt) {
      await sendCardReaddNotice(server, cardCents, "final", now);
    } else {
      await sendCardReaddNotice(server, cardCents, "reminder", now);
    }
    return;
  }
  if (rung === CARD_READD_REMINDER_DAYS.length + 1) {
    await sendCardReaddNotice(server, cardCents, "final", now);
    return;
  }
  // Final notice already sent: hold until the grace deadline, nothing more to say.
  await rescheduleAttempt(server, graceUntil);
}

/** One rung of the ladder above: email + bell + audit + the next rung's schedule. */
async function sendCardReaddNotice(
  server: DueServer,
  cardCents: number,
  stage: "first" | "reminder" | "final",
  now: Date,
): Promise<void> {
  const graceUntil = server.billingGraceUntil!;
  const user = server.user;
  const newStage = server.dunningStage + 1;
  // What the customer is told comes from the state we are about to WRITE.
  const nextAt =
    stage === "final"
      ? graceUntil
      : (() => {
          const idx = Math.min(newStage - 1, CARD_READD_REMINDER_DAYS.length - 1);
          const firstNoticeAt = server.dunningNextAt
            ? new Date(server.dunningNextAt.getTime() - CARD_READD_REMINDER_DAYS[Math.max(0, idx - 1)] * DAY)
            : now;
          const scheduled =
            newStage <= CARD_READD_REMINDER_DAYS.length
              ? new Date(firstNoticeAt.getTime() + CARD_READD_REMINDER_DAYS[newStage - 1] * DAY)
              : new Date(graceUntil.getTime() - DAY);
          const floor = new Date(now.getTime() + MIN_RETRY_GAP_MS);
          const at = scheduled > floor ? scheduled : floor;
          // Never schedule past the grace deadline itself.
          return at < graceUntil ? at : graceUntil;
        })();
  await db.server.update({ where: { id: server.id }, data: { dunningStage: newStage, dunningNextAt: nextAt } });
  server.dunningStage = newStage;
  server.dunningNextAt = nextAt;

  const retired = await db.paymentCard.findFirst({
    where: { userId: server.userId, unusableAt: { not: null } },
    orderBy: { unusableAt: "desc" },
  });
  const cardLabel = (retired && cardDisplayLabel(retired)) || savedCardLabel(user) || "Saved card";
  await mail(
    user.email,
    user.id,
    emails.cardReaddRequired(server.hostname, fmtUsd(cardCents), cardLabel, fmtDay(graceUntil), billingUrl(), stage),
  );
  await notify(
    server.userId,
    stage === "final"
      ? `${server.hostname} — add a card by ${fmtDay(graceUntil)} to avoid a pause`
      : `${server.hostname} — please re-add your card`,
    stage === "final"
      ? `We've held ${server.hostname} open while waiting for a chargeable card. It pauses on ${fmtDay(graceUntil)} unless a card is added. Nothing is deleted either way.`
      : `The card saved for ${server.hostname} can't be charged again on our side (our fault, not a decline). Add it again and the ${fmtUsd(cardCents)} renewal completes automatically. Running until at least ${fmtDay(graceUntil)}.`,
    "/dashboard/billing",
  );
  await db.auditLog
    .create({
      data: {
        userId: server.userId,
        action: "billing.card_readd_notice",
        detail: `${server.id}: ${stage} notice (rung ${newStage}) for ${fmtUsd(cardCents)}, grace until ${graceUntil.toISOString().slice(0, 10)}`,
      },
    })
    .catch(() => {});
  console.log(`[billing] ${server.hostname}: re-add-card ${stage} notice sent (rung ${newStage}), grace until ${graceUntil.toISOString()}`);
}

/**
 * The saved card is PERMANENTLY unusable at Stripe (see
 * lib/stripe-charge-errors.ts) — a fault on OUR side. Retire it, grant the
 * platform grace, and send the first re-add notice. Idempotent per period: a
 * second call for the same server extends nothing and re-sends nothing once the
 * grace is already in effect.
 */
async function retireUnusableCard(opts: {
  server: DueServer;
  cardCents: number;
  now: Date;
  reason: NonNullable<Extract<OffSessionResult, { kind: "unavailable" }>["reason"]>;
  message: string;
}): Promise<void> {
  const { server, cardCents, now, reason, message } = opts;
  console.warn(`[billing] saved card unusable for ${server.hostname} (${reason}): ${message}`);
  await forgetMissingPaymentMethod(server.userId, reason).catch((e) =>
    console.error("[billing] could not retire unusable payment method", e),
  );
  // `server.user` is deliberately NOT mutated: this pass keeps the card-customer
  // runway; the grace below is what governs suspension from here on.
  const alreadyInGrace = server.billingGraceUntil && server.billingGraceUntil > now;
  const graceUntil = alreadyInGrace
    ? server.billingGraceUntil!
    : new Date(Math.max(now.getTime() + PLATFORM_FAULT_GRACE_DAYS * DAY, server.expiresAt!.getTime() + PLATFORM_FAULT_GRACE_DAYS * DAY));
  await db.server.update({
    where: { id: server.id },
    data: { billingGraceUntil: graceUntil, dunningStage: 0, dunningNextAt: null, dunningPayUrl: null },
  });
  server.billingGraceUntil = graceUntil;
  server.dunningStage = 0;
  server.dunningNextAt = null;
  server.dunningPayUrl = null;
  await db.auditLog
    .create({
      data: {
        userId: server.userId,
        action: "billing.card_unusable_grace",
        detail: `${server.id}: ${reason} — grace until ${graceUntil.toISOString().slice(0, 10)}; ${message.slice(0, 140)}`,
      },
    })
    .catch(() => {});
  if (!alreadyInGrace) await sendCardReaddNotice(server, cardCents, "first", now);
}

