/**
 * The saved card is PERMANENTLY unusable at Stripe (see
 * lib/stripe-charge-errors.ts) — a fault on OUR side. Retire it, grant the
 * platform grace, and send the first re-add notice. Idempotent per period: a
 * second call for the same server extends nothing and re-sends nothing once the
 * grace is already in effect.
 */
async function retireUnusableCard(opts: {
  server: DueServer;
  cardCents: number;
  now: Date;
  reason: NonNullable<Extract<OffSessionResult, { kind: "unavailable" }>["reason"]>;
  message: string;
}): Promise<void> {
  const { server, cardCents, now, reason, message } = opts;
  console.warn(`[billing] saved card unusable for ${server.hostname} (${reason}): ${message}`);
  await forgetMissingPaymentMethod(server.userId, reason).catch((e) =>
    console.error("[billing] could not retire unusable payment method", e),
  );
  // `server.user` is deliberately NOT mutated: this pass keeps the card-customer
  // runway; the grace below is what governs suspension from here on.
  const alreadyInGrace = server.billingGraceUntil && server.billingGraceUntil > now;
  const graceUntil = alreadyInGrace
    ? server.billingGraceUntil!
    : new Date(Math.max(now.getTime() + PLATFORM_FAULT_GRACE_DAYS * DAY, server.expiresAt!.getTime() + PLATFORM_FAULT_GRACE_DAYS * DAY));
  await db.server.update({
    where: { id: server.id },
    data: { billingGraceUntil: graceUntil, dunningStage: 0, dunningNextAt: null, dunningPayUrl: null },
  });
  server.billingGraceUntil = graceUntil;
  server.dunningStage = 0;
  server.dunningNextAt = null;
  server.dunningPayUrl = null;
  await db.auditLog
    .create({
      data: {
        userId: server.userId,
        action: "billing.card_unusable_grace",
        detail: `${server.id}: ${reason} — grace until ${graceUntil.toISOString().slice(0, 10)}; ${message.slice(0, 140)}`,
      },
    })
    .catch(() => {});
  if (!alreadyInGrace) await sendCardReaddNotice(server, cardCents, "first", now);
}

