/* ------------------------------------------------------------------ *
 * Card health (2026-10-01) — unusable saved cards + platform-fault grace
 * ------------------------------------------------------------------ */

/**
 * Send the "please re-add your card" email to ONE customer, by hand, from the
 * admin card-health page (app/admin/billing/card-health). Same template the
 * worker sends automatically (`emails.cardReaddRequired`, stage "first"), so
 * admin and automation never say two different things. Idempotency is the
 * operator's — the page shows when the last one went out — but a repeat is
 * rate-limited here to one per customer per 20 hours so a double-click cannot
 * send two.
 *
 * `requireArea("billing")`: the same gate every other action in this file uses.
 * The email is addressed to the customer's account email only.
 */
export async function adminSendReaddCardEmail(
  userId: string,
): Promise<{ ok?: true; error?: string; message?: string }> {
  const admin = await requireArea("billing");
  const user = await db.user.findUnique({
    where: { id: userId },
    select: { id: true, email: true, cardBrand: true, cardLast4: true, cardExpMonth: true, cardExpYear: true },
  });
  if (!user) return { error: "Customer not found." };
  const recent = await db.emailLog.findFirst({
    where: { userId, template: { in: ["card_readd_required", "card_readd_reminder"] }, createdAt: { gt: new Date(Date.now() - 20 * 3600_000) } },
    select: { createdAt: true },
  });
  if (recent) return { error: `A re-add-card email already went to this customer at ${recent.createdAt.toISOString().slice(0, 16).replace("T", " ")} UTC — not sending another within 20 hours.` };

  // The server(s) this is about: the soonest-expiring paid, auto-renewing one.
  const server = await db.server.findFirst({
    where: { userId, isFree: false, status: { in: ["RUNNING", "STOPPED"] } },
    orderBy: { expiresAt: "asc" },
    include: { plan: true, gamePlan: true, dedicatedIp: true },
  });
  if (!server) return { error: "This customer has no active paid server to renew." };
  const retired = await db.paymentCard.findFirst({ where: { userId, unusableAt: { not: null } }, orderBy: { unusableAt: "desc" } });
  const { cardDisplayLabel } = await import("@/lib/stripe-cards");
  const { renewalQuote } = await import("@/lib/renewal-quote");
  const { dedicatedIpMonthlyCents } = await import("@/lib/dedicated-ip");
  const { extraDiskPerGbCents } = await import("@/lib/disk-expand");
  const { backupPlusMonthlyCents } = await import("@/lib/backup-upgrade");
  const { annualDiscountPct } = await import("@/lib/annual-discount");
  const quote = renewalQuote(server, {
    ipMonthlyCents: await dedicatedIpMonthlyCents(),
    extraDiskPerGbCents: await extraDiskPerGbCents(),
    backupPlusCents: await backupPlusMonthlyCents(),
    annualDiscountPct: await annualDiscountPct(),
  });
  const graceUntil =
    server.billingGraceUntil && server.billingGraceUntil > new Date()
      ? server.billingGraceUntil
      : new Date(Math.max(Date.now(), server.expiresAt?.getTime() ?? Date.now()) + 7 * 86400_000);
  const fmtDay = (d: Date) => d.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" });
  const cardLabel =
    (retired && cardDisplayLabel(retired)) ||
    cardDisplayLabel({ brand: user.cardBrand, last4: user.cardLast4, expMonth: user.cardExpMonth, expYear: user.cardExpYear }) ||
    "Saved card";
  const { emails, sendMail } = await import("@/lib/mailer");
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const tpl = emails.cardReaddRequired(
    server.hostname,
    `$${(quote.totalCents / 100).toFixed(2)}`,
    cardLabel,
    fmtDay(graceUntil),
    `${base}/dashboard/billing`,
    "first",
  );
  const sent = await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, template: tpl.template, userId, kind: "payment_failed" });
  await audit(admin.id, "billing.readd_card_email", `${userId} (${user.email}) for ${server.hostname} — ${sent ? "sent" : "NOT sent (mailer)"}`);
  revalidatePath("/admin/billing/card-health");
  return sent ? { ok: true, message: `Sent to ${user.email}.` } : { error: "The mailer did not accept the message — check the Email log." };
}

/**
 * Push one server's platform-fault grace out by N days (1..60). The grace is a
 * FLOOR on the suspension date (worker/billing.ts suspendDueAt), so this can only
 * ever buy the customer time, never shorten it; it never moves `expiresAt` and
 * never changes what the renewal costs — use "Extend" on the server page for a
 * gifted term. If no grace is in effect it starts from now (or the expiry,
 * whichever is later). Audit-logged with before/after.
 */
export async function adminExtendBillingGrace(
  serverId: string,
  days: number,
): Promise<{ ok?: true; error?: string; message?: string; graceUntil?: string }> {
  const admin = await requireArea("billing");
  const n = Math.round(Number(days));
  if (!Number.isFinite(n) || n < 1 || n > 60) return { error: "Days must be between 1 and 60." };
  const server = await db.server.findUnique({ where: { id: serverId }, select: { id: true, hostname: true, expiresAt: true, billingGraceUntil: true, status: true } });
  if (!server) return { error: "Server not found." };
  const now = Date.now();
  const from = Math.max(server.billingGraceUntil?.getTime() ?? 0, server.expiresAt?.getTime() ?? 0, now);
  const next = new Date(from + n * 86400_000);
  await db.server.update({ where: { id: serverId }, data: { billingGraceUntil: next } });
  await audit(
    admin.id,
    "billing.grace_extended",
    `${serverId} (${server.hostname}): +${n}d — ${server.billingGraceUntil?.toISOString().slice(0, 10) ?? "none"} -> ${next.toISOString().slice(0, 10)}`,
  );
  revalidatePath("/admin/billing/card-health");
  revalidatePath(`/admin/servers/${serverId}`);
  return { ok: true, message: `${server.hostname} will not be suspended before ${next.toISOString().slice(0, 10)}.`, graceUntil: next.toISOString() };
}
EOF
