"use client";

import { useState, useTransition } from "react";
import { adminExtendBillingGrace, adminSendReaddCardEmail } from "@/lib/actions-admin-billing";

/**
 * Per-row controls for /admin/billing/card-health: one-click "send re-add-card
 * email" (confirm first — it emails a real customer) and a small "+N days grace"
 * form. Both call `requireArea("billing")` server actions that audit-log.
 */
export function SendReaddEmailButton({ userId, email }: { userId: string; email: string }) {
  const [pending, start] = useTransition();
  const [confirm, setConfirm] = useState(false);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const send = () =>
    start(async () => {
      const res = await adminSendReaddCardEmail(userId);
      setConfirm(false);
      setMsg(res.ok ? { ok: true, text: res.message ?? "Sent." } : { ok: false, text: res.error ?? "Failed." });
    });
  return (
    <div className="flex flex-col items-start gap-1">
      {!confirm ? (
        <button type="button" className="btn-secondary py-1 text-xs" onClick={() => setConfirm(true)} disabled={pending}>
          Send re-add-card email
        </button>
      ) : (
        <div className="flex items-center gap-1.5">
          <span className="text-xs text-slate-300">Email {email}?</span>
          <button type="button" className="btn-primary py-1 text-xs" onClick={send} disabled={pending}>
            {pending ? "Sending…" : "Send"}
          </button>
          <button type="button" className="btn-ghost py-1 text-xs" onClick={() => setConfirm(false)} disabled={pending}>
            Cancel
          </button>
        </div>
      )}
      {msg && <span className={"text-[11px] " + (msg.ok ? "text-emerald-400" : "text-red-400")}>{msg.text}</span>}
    </div>
  );
}

export function ExtendGraceForm({ serverId }: { serverId: string }) {
  const [pending, start] = useTransition();
  const [days, setDays] = useState(7);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const submit = () =>
    start(async () => {
      const res = await adminExtendBillingGrace(serverId, days);
      setMsg(res.ok ? { ok: true, text: res.message ?? "Extended." } : { ok: false, text: res.error ?? "Failed." });
    });
  return (
    <div className="flex flex-col items-start gap-1">
      <div className="flex items-center gap-1.5">
        <input
          type="number"
          min={1}
          max={60}
          value={days}
          onChange={(e) => setDays(Number(e.target.value))}
          className="input w-16 py-1 text-xs"
          aria-label="Grace days"
        />
        <button type="button" className="btn-secondary py-1 text-xs" onClick={submit} disabled={pending}>
          {pending ? "Saving…" : "+ days grace"}
        </button>
      </div>
      {msg && <span className={"text-[11px] " + (msg.ok ? "text-emerald-400" : "text-red-400")}>{msg.text}</span>}
    </div>
  );
}

