          </button>
        </div>
      )}
      {msg && <span className={"text-[11px] " + (msg.ok ? "text-emerald-400" : "text-red-400")}>{msg.text}</span>}
    </div>
  );
}

export function ExtendGraceForm({ serverId }: { serverId: string }) {
  const [pending, start] = useTransition();
  const [days, setDays] = useState(7);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const submit = () =>
    start(async () => {
      const res = await adminExtendBillingGrace(serverId, days);
