import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatCard, Badge, fmtMoney } from "@/components/ui/primitives";
import { ExtendGraceForm, SendReaddEmailButton } from "@/components/admin/CardHealthControls";
import { renewalQuote } from "@/lib/renewal-quote";
import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { extraDiskPerGbCents } from "@/lib/disk-expand";
import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
import { annualDiscountPct } from "@/lib/annual-discount";
import { walletSplit } from "@/lib/wallet-split";
import { unusableCardReasonLabel } from "@/lib/stripe-charge-errors";

export const dynamic = "force-dynamic";

/**
 * Card health — who is about to be renewed on a card that cannot be charged.
 *
 * Built for the 2026-10-01 incident (saved PaymentMethods Stripe refuses to
 * reuse — see lib/stripe-charge-errors.ts). Lists every paid, auto-renewing,
 * non-free server due within the horizon whose wallet does NOT cover the
 * renewal, with the owner's card state: retired-unusable, none, or a card the
 * flag script has not vetted yet. Everything here is computed from our own DB
 * — no Stripe calls on render (the flag script does the Stripe vetting).
 */
const HORIZON_DAYS = 14;

export default async function CardHealthPage() {
  await requireArea("billing");
  const now = new Date();
  const horizon = new Date(now.getTime() + HORIZON_DAYS * 86400_000);

  const [servers, prices, unusableCards, recentNotices] = await Promise.all([
    db.server.findMany({
      where: { isFree: false, status: { in: ["RUNNING", "STOPPED"] }, expiresAt: { lt: horizon } },
      include: {
        plan: true,
        gamePlan: true,
        dedicatedIp: true,
        user: {
          select: {
            id: true, email: true, name: true, balanceCents: true,
            stripeCustomerId: true, stripePaymentMethodId: true, cardBrand: true, cardLast4: true,
            paymentCards: { select: { id: true, brand: true, last4: true, isPrimary: true, unusableAt: true, unusableReason: true, createdAt: true } },
          },
        },
      },
      orderBy: { expiresAt: "asc" },
    }),
    (async () => ({
      ipMonthlyCents: await dedicatedIpMonthlyCents(),
      extraDiskPerGbCents: await extraDiskPerGbCents(),
      backupPlusCents: await backupPlusMonthlyCents(),
      annualDiscountPct: await annualDiscountPct(),
    }))(),
    db.paymentCard.count({ where: { unusableAt: { not: null } } }),
    db.emailLog.findMany({
      where: { template: { in: ["card_readd_required", "card_readd_reminder", "card_readd_final_notice"] }, createdAt: { gt: new Date(now.getTime() - 30 * 86400_000) } },
      select: { userId: true, createdAt: true, template: true },
      orderBy: { createdAt: "desc" },
    }),
  ]);

  const lastNoticeFor = new Map<string, { at: Date; template: string }>();
  for (const n of recentNotices) if (n.userId && !lastNoticeFor.has(n.userId)) lastNoticeFor.set(n.userId, { at: n.createdAt, template: n.template ?? "" });

  type Row = {
    serverId: string; hostname: string; expiresAt: Date; autoRenew: boolean; dueCents: number; cardCents: number;
    user: (typeof servers)[number]["user"]; cardState: "unusable" | "none" | "unvetted" | "ok"; cardLabel: string;
    graceUntil: Date | null; dunningStage: number; suspended: boolean;
  };
  const rows: Row[] = [];
  for (const s of servers) {
    // Tax deliberately NOT folded in here: this page triages card state, and the
    // owner's rate needs a per-user lookup the sweep does itself. Shown as "ex. tax".
    const dueCents = renewalQuote(s, prices).totalCents;
    const split = walletSplit({ dueCents, balanceCents: s.user.balanceCents, useWallet: true });
    if (split.cardCents === 0) continue; // the wallet covers it — no card involved
    const usable = s.user.paymentCards.filter((c) => !c.unusableAt);
    const unusable = s.user.paymentCards.filter((c) => c.unusableAt);
    const hasMirror = !!(s.user.stripeCustomerId && s.user.stripePaymentMethodId);
    const cardState: Row["cardState"] = hasMirror && usable.length > 0 ? "ok" : unusable.length > 0 ? "unusable" : hasMirror ? "unvetted" : "none";
    const c = usable[0] ?? unusable[0];
    rows.push({
      serverId: s.id, hostname: s.hostname, expiresAt: s.expiresAt!, autoRenew: s.autoRenew, dueCents, cardCents: split.cardCents,
      user: s.user, cardState,
      cardLabel: c ? `${c.brand ?? "card"} ···· ${c.last4 ?? "????"}` : s.user.cardLast4 ? `${s.user.cardBrand ?? "card"} ···· ${s.user.cardLast4}` : "—",
      graceUntil: s.billingGraceUntil, dunningStage: s.dunningStage, suspended: s.status === "SUSPENDED",
    });
  }
  const atRisk = rows.filter((r) => r.cardState !== "ok");
  const expired = rows.filter((r) => r.expiresAt < now);

  const tone = (st: Row["cardState"]) => (st === "unusable" ? "red" : st === "none" ? "amber" : st === "unvetted" ? "slate" : "green") as "red" | "amber" | "slate" | "green";
  const stateLabel = (st: Row["cardState"]) => ({ unusable: "Card unusable", none: "No card", unvetted: "Card unvetted", ok: "Card OK" })[st];
  const day = (d: Date) => d.toISOString().slice(0, 10);

  return (
    <div>
      <PageHeader
        title="Card health"
        sub={`Paid servers due within ${HORIZON_DAYS} days whose wallet does not cover the renewal, with the owner's saved-card state. Amounts ex. tax.`}
      >
        <Link href="/admin/billing" className="btn-ghost py-1.5 text-xs">Billing</Link>
      </PageHeader>

      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Needs a card" value={String(atRisk.length)} hint={`of ${rows.length} card-dependent renewals`} />
        <StatCard label="Already expired" value={String(expired.filter((r) => r.cardState !== "ok").length)} hint="unrenewed, not suspended, no usable card" />
        <StatCard label="Retired cards" value={String(unusableCards)} hint="PaymentCard rows flagged unusable" />
        <StatCard label="Exposure" value={fmtMoney(atRisk.reduce((n, r) => n + r.cardCents, 0))} hint="card legs we cannot collect today" />
      </div>

      <div className="card overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left text-xs uppercase tracking-wide text-slate-400">
              <th className="px-3 py-2">Server</th>
              <th className="px-3 py-2">Expires</th>
              <th className="px-3 py-2">Due / card leg</th>
              <th className="px-3 py-2">Customer</th>
              <th className="px-3 py-2">Card</th>
              <th className="px-3 py-2">Grace</th>
              <th className="px-3 py-2">Actions</th>
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 && (
              <tr><td colSpan={7} className="px-3 py-6 text-center text-slate-400">No card-dependent renewals due in the next {HORIZON_DAYS} days.</td></tr>
            )}
            {rows.map((r) => {
              const last = lastNoticeFor.get(r.user.id);
              const retired = r.user.paymentCards.find((c) => c.unusableAt);
              return (
                <tr key={r.serverId} className="border-t border-white/5 align-top">
                  <td className="px-3 py-2">
                    <Link href={`/admin/servers/${r.serverId}`} className="font-medium text-white hover:underline">{r.hostname}</Link>
                    <div className="text-[11px] text-slate-500">{r.autoRenew ? "auto-renew on" : "auto-renew OFF"}{r.dunningStage > 0 ? ` · ladder rung ${r.dunningStage}` : ""}</div>
                  </td>
                  <td className="px-3 py-2 whitespace-nowrap">
                    <span className={r.expiresAt < now ? "text-red-300" : ""}>{day(r.expiresAt)}</span>
                    {r.expiresAt < now && <div className="text-[11px] text-red-400">expired</div>}
                  </td>
                  <td className="px-3 py-2 whitespace-nowrap">
                    {fmtMoney(r.dueCents)}
                    <div className="text-[11px] text-slate-500">card {fmtMoney(r.cardCents)} · wallet {fmtMoney(r.user.balanceCents)}</div>
                  </td>
                  <td className="px-3 py-2">
                    <Link href={`/admin/users/${r.user.id}`} className="text-white hover:underline">{r.user.email}</Link>
                    {last && <div className="text-[11px] text-slate-500">last notice {day(last.at)} ({last.template.replace("card_readd_", "")})</div>}
                  </td>
                  <td className="px-3 py-2">
                    <Badge tone={tone(r.cardState)}>{stateLabel(r.cardState)}</Badge>
                    <div className="mt-1 text-[11px] text-slate-400">{r.cardLabel}</div>
                    {retired && <div className="text-[11px] text-slate-500">{unusableCardReasonLabel(retired.unusableReason)}</div>}
                  </td>
                  <td className="px-3 py-2 whitespace-nowrap text-[12px]">
                    {r.graceUntil ? <span className={r.graceUntil > now ? "text-emerald-300" : "text-slate-400"}>until {day(r.graceUntil)}</span> : <span className="text-slate-500">—</span>}
                  </td>
                  <td className="px-3 py-2">
                    <div className="flex flex-col gap-2">
                      {r.cardState !== "ok" && <SendReaddEmailButton userId={r.user.id} email={r.user.email} />}
                      <ExtendGraceForm serverId={r.serverId} />
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <p className="mt-4 text-xs text-slate-500">
        &ldquo;Card unvetted&rdquo; = a card on file that nothing has yet confirmed is attached at Stripe; run
        <code className="mx-1">scripts/flag-unusable-payment-cards.ts</code> (dry-run first) to vet every saved card. &ldquo;Card unusable&rdquo; cards
        were retired by the worker or that script and will never be charged again; the customer must re-add the card.
        Grace is a floor on the suspension date only — it never changes the price or the expiry.
      </p>
    </div>
  );
}

