/**
 * Vet every saved card against Stripe and RETIRE the ones that can never be
 * charged again (2026-10-01 incident — see lib/stripe-charge-errors.ts).
 *
 * WHAT IT CHECKS. For each `PaymentCard` row (and each `User.stripePaymentMethodId`
 * with no row), `paymentMethods.retrieve` — a READ — and compare `pm.customer`
 * with the account's `stripeCustomerId`. A method whose `customer` is null was
 * consumed by a guest PaymentIntent or detached (Stripe: "may not be used
 * again"); a different customer id means it was saved under another profile.
 * Either way `markPaymentMethodUnusable` retires it: the row is kept and
 * flagged, the primary flag moves to the next usable card (or the User mirror
 * is cleared so the sweep stops trying it), and a `card.unusable` audit row is
 * written. A method that is attached to the right customer is left alone.
 *
 * NEVER charges, attaches, detaches or creates anything at Stripe. Stripe calls
 * are retrieve-only. DB writes happen only with --apply.
 *
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/flag-unusable-payment-cards.ts            # dry run (default)
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/flag-unusable-payment-cards.ts --apply    # retire the unusable ones
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/flag-unusable-payment-cards.ts --apply --notify
 *       # ALSO email each affected customer who owns a paid, auto-renewing server
 *       # the "please re-add your card" notice (emails.cardReaddRequired "first")
 *       # and grant PLATFORM grace (7 days from now, or from expiry if later) on
 *       # those servers so none is suspended before being told. One email per
 *       # customer per run; skipped if one went out in the last 20 hours.
 *
 * Idempotent: an already-retired row is skipped; grace is only ever pushed later.
 */

import { assertDbTarget } from "./db-target-guard";
assertDbTarget("flag-unusable-payment-cards.ts");

import { db } from "../lib/db";
import { stripe, stripeConfigured } from "../lib/stripe";
import { paymentMethodUnusableReason, type UnusableCardReason } from "../lib/stripe-charge-errors";
import { asStripeError } from "../lib/stripe-charge-errors";

const APPLY = process.argv.includes("--apply");
const NOTIFY = process.argv.includes("--notify");
const GRACE_DAYS = 7;
const DAY = 86_400_000;

async function main() {
  if (!stripeConfigured()) {
    console.error("[flag-cards] Stripe is not configured in this environment — refusing to run.");
    process.exitCode = 1;
    return;
  }
  const mode = (process.env.STRIPE_SECRET_KEY ?? "").startsWith("sk_live_") ? "LIVE" : "TEST";
  console.log(`[flag-cards] Stripe ${mode} mode (retrieve-only) — ${APPLY ? "APPLY" : "DRY RUN"}${NOTIFY ? " + NOTIFY" : ""}\n`);

  // Every method we believe is on file: PaymentCard rows plus any legacy
  // User-mirror-only id (a card saved before the PaymentCard table existed).
  const rows = await db.paymentCard.findMany({
    where: { unusableAt: null },
    include: { user: { select: { id: true, email: true, stripeCustomerId: true, stripePaymentMethodId: true } } },
    orderBy: { createdAt: "asc" },
  });
  const mirrorOnly = await db.user.findMany({
    where: { stripePaymentMethodId: { not: null }, paymentCards: { none: {} } },
    select: { id: true, email: true, stripeCustomerId: true, stripePaymentMethodId: true },
  });
  type Item = { userId: string; email: string; customerId: string | null; pmId: string; source: "row" | "mirror" };
  const items: Item[] = [
    ...rows.map((r) => ({ userId: r.userId, email: r.user.email, customerId: r.user.stripeCustomerId, pmId: r.stripePaymentMethodId, source: "row" as const })),
    ...mirrorOnly.map((u) => ({ userId: u.id, email: u.email, customerId: u.stripeCustomerId, pmId: u.stripePaymentMethodId!, source: "mirror" as const })),
  ];
  console.log(`[flag-cards] ${rows.length} PaymentCard row(s) + ${mirrorOnly.length} mirror-only id(s) to vet\n`);

  const bad: (Item & { reason: UnusableCardReason; detail: string })[] = [];
  let ok = 0, errors = 0;
  for (const it of items) {
    try {
      const pm = await stripe().paymentMethods.retrieve(it.pmId);
      const reason = paymentMethodUnusableReason(pm, it.customerId);
      const label = `${pm.card?.brand ?? "card"} ····${pm.card?.last4 ?? "????"}`;
      if (!reason) {
        ok++;
        continue;
      }
      const pmCust = typeof pm.customer === "string" ? pm.customer : (pm.customer?.id ?? null);
      bad.push({ ...it, reason, detail: `${label} pm.customer=${pmCust ?? "null"} ours=${it.customerId ?? "null"}` });
    } catch (e) {
      const err = asStripeError(e);
      if (err?.code === "resource_missing") {
        bad.push({ ...it, reason: "missing_at_stripe", detail: "no longer exists at Stripe" });
      } else {
        errors++;
        console.error(`  !! ${it.email} ${it.pmId}: ${(e as Error)?.message ?? e}`);
      }
    }
  }

  console.log(`[flag-cards] attached + chargeable: ${ok}`);
  console.log(`[flag-cards] UNUSABLE: ${bad.length}   errors: ${errors}\n`);
  for (const b of bad) console.log(`  ${b.email}  ${b.pmId}  [${b.source}]  ${b.reason}  — ${b.detail}`);

  if (!APPLY) {
    console.log("\n[flag-cards] dry run — nothing written. Re-run with --apply to retire these cards.");
    return;
  }

  const { markPaymentMethodUnusable } = await import("../lib/stripe-cards");
  const affectedUsers = new Set<string>();
  for (const b of bad) {
    await markPaymentMethodUnusable(b.userId, b.pmId, b.reason);
    affectedUsers.add(b.userId);
    console.log(`  retired ${b.pmId} for ${b.email} (${b.reason})`);
  }
  console.log(`\n[flag-cards] retired ${bad.length} card(s) across ${affectedUsers.size} customer(s)`);

  if (!NOTIFY) {
    console.log("[flag-cards] --notify not given: no emails sent, no grace granted. The worker will grant grace + notify on each server's next failed renewal attempt.");
    return;
  }

  const { emails, sendMail } = await import("../lib/mailer");
  const { cardDisplayLabel } = await import("../lib/stripe-cards");
  const { renewalQuote } = await import("../lib/renewal-quote");
  const { dedicatedIpMonthlyCents } = await import("../lib/dedicated-ip");
  const { extraDiskPerGbCents } = await import("../lib/disk-expand");
  const { backupPlusMonthlyCents } = await import("../lib/backup-upgrade");
  const { annualDiscountPct } = await import("../lib/annual-discount");
  const prices = {
    ipMonthlyCents: await dedicatedIpMonthlyCents(),
    extraDiskPerGbCents: await extraDiskPerGbCents(),
    backupPlusCents: await backupPlusMonthlyCents(),
    annualDiscountPct: await annualDiscountPct(),
  };
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const fmtDay = (d: Date) => d.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" });
  const now = Date.now();

  for (const userId of affectedUsers) {
    const user = await db.user.findUnique({ where: { id: userId }, select: { email: true, stripePaymentMethodId: true } });
    if (!user) continue;
    if (user.stripePaymentMethodId) {
      console.log(`  ${user.email}: still has a usable card — no email needed`);
      continue;
    }
    const servers = await db.server.findMany({
      where: { userId, isFree: false, autoRenew: true, status: { in: ["RUNNING", "STOPPED"] } },
      include: { plan: true, gamePlan: true, dedicatedIp: true },
      orderBy: { expiresAt: "asc" },
    });
    if (servers.length === 0) {
      console.log(`  ${user.email}: no auto-renewing paid server — no email`);
      continue;
    }
    // Grace on EVERY affected server, so none is suspended before being told.
    let graceUntil = new Date(0);
    for (const s of servers) {
      const g = new Date(Math.max(now, s.expiresAt?.getTime() ?? now) + GRACE_DAYS * DAY);
      const next = s.billingGraceUntil && s.billingGraceUntil > g ? s.billingGraceUntil : g;
      await db.server.update({ where: { id: s.id }, data: { billingGraceUntil: next } });
      if (next > graceUntil) graceUntil = next;
    }
    const recent = await db.emailLog.findFirst({
      where: { userId, template: { in: ["card_readd_required", "card_readd_reminder"] }, createdAt: { gt: new Date(now - 20 * 3600_000) } },
    });
    if (recent) {
      console.log(`  ${user.email}: notice already sent at ${recent.createdAt.toISOString()} — skipped`);
      continue;
    }
    const first = servers[0];
    const quote = renewalQuote(first, prices);
    const retired = await db.paymentCard.findFirst({ where: { userId, unusableAt: { not: null } }, orderBy: { unusableAt: "desc" } });
    const tpl = emails.cardReaddRequired(
      first.hostname,
      `$${(quote.totalCents / 100).toFixed(2)}`,
      (retired && cardDisplayLabel(retired)) || "Saved card",
      fmtDay(graceUntil),
      `${base}/dashboard/billing`,
      "first",
    );
    const sent = await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, template: tpl.template, userId, kind: "payment_failed" });
    // Mark rung 1 on each server so the worker's ladder continues with the day-1 reminder, not a second first notice.
    for (const s of servers) {
      await db.server.update({ where: { id: s.id }, data: { dunningStage: 1, dunningNextAt: new Date(now + DAY), dunningPayUrl: null } });
    }
    await db.auditLog.create({ data: { userId, action: "billing.card_readd_notice", detail: `script: first notice for ${first.hostname}, grace until ${graceUntil.toISOString().slice(0, 10)} — ${sent ? "sent" : "NOT sent"}` } });
    console.log(`  ${user.email}: ${sent ? "emailed" : "EMAIL FAILED"} (${first.hostname}, grace until ${graceUntil.toISOString().slice(0, 10)})`);
  }
}

main()
  .catch((e) => {
    console.error(e);
    process.exitCode = 1;
  })
  .finally(() => db.$disconnect());

