/**
 * Stripe TEST-MODE verification for the saved-card reuse fix (2026-10-01).
 *
 * Reproduces, against the real Stripe test API, every PaymentMethod lifecycle
 * the renewal sweep can meet, and asserts that `classifyChargeError` +
 * `paymentMethodUnusableReason` (lib/stripe-charge-errors.ts) classify each the
 * way worker/billing.ts now relies on:
 *
 *   A  PM consumed by a GUEST PaymentIntent (no customer)        -> reuse fails, "not_reusable"
 *   B  PM used on a PI WITH customer but NO setup_future_usage    -> reuse fails, "not_reusable"
 *      (this was our outstanding-balance "settle" checkout — the live bug)
 *   C  PM used WITH customer AND setup_future_usage=off_session   -> attached, off-session reuse SUCCEEDS
 *   D  PM attached then DETACHED (customer removed the card)      -> reuse fails, "not_reusable"
 *   E  SCA-required test card, attached                           -> "requires_action"
 *   F  declining test card, attached                              -> "declined" (insufficient_funds)
 *   G  nonexistent PM id                                          -> "missing_at_stripe"
 *
 * REFUSES to run with anything but an sk_test_ key, creates one throwaway test
 * customer and deletes it at the end. No database access at all.
 *
 *   STRIPE_SECRET_KEY=sk_test_... npx tsx scripts/verify-card-reuse-testmode.ts
 */
import Stripe from "stripe";
import { classifyChargeError, paymentMethodUnusableReason } from "../lib/stripe-charge-errors";

const key = process.env.STRIPE_SECRET_KEY ?? "";
if (!key.startsWith("sk_test_")) {
  console.error("refusing: STRIPE_SECRET_KEY is not a TEST key (sk_test_...)");
  process.exit(2);
}
const stripe = new Stripe(key);
const tag = `verify-card-reuse-${Date.now()}`;
let failures = 0;
function check(label: string, cond: boolean, detail = "") {
  console.log(`${cond ? "PASS" : "FAIL"}  ${label}${detail ? ` — ${detail}` : ""}`);
  if (!cond) failures++;
}

async function freshPm(token = "tok_visa") {
  return stripe.paymentMethods.create({ type: "card", card: { token } });
}
async function offSession(customer: string, pm: string, label: string) {
  try {
    const pi = await stripe.paymentIntents.create({
      amount: 620, currency: "usd", customer, payment_method: pm, confirm: true, off_session: true,
      automatic_payment_methods: { enabled: true, allow_redirects: "never" }, description: `${tag} ${label}`,
    });
    return { ok: true as const, status: pi.status };
  } catch (e) {
    return { ok: false as const, result: classifyChargeError(e), error: e };
  }
}

async function main() {
  const customer = await stripe.customers.create({ email: `${tag}@example.test`, metadata: { nxeonTest: tag } });
  try {
    // A — guest PI
    {
      const pm = await freshPm();
      await stripe.paymentIntents.create({ amount: 899, currency: "usd", payment_method: pm.id, confirm: true, automatic_payment_methods: { enabled: true, allow_redirects: "never" }, description: `${tag} A` });
      const after = await stripe.paymentMethods.retrieve(pm.id);
      check("A: guest-consumed PM is reported unusable by paymentMethodUnusableReason", paymentMethodUnusableReason(after, customer.id) === "not_reusable");
      const r = await offSession(customer.id, pm.id, "A");
      check("A: off-session reuse fails and classifies as unavailable/not_reusable", !r.ok && r.result.kind === "unavailable" && r.result.reason === "not_reusable", !r.ok ? r.result.message.slice(0, 80) : "charge unexpectedly succeeded");
    }
    // B — customer on the PI, no setup_future_usage (the live bug's shape)
    {
      const pm = await freshPm();
      await stripe.paymentIntents.create({ amount: 899, currency: "usd", customer: customer.id, payment_method: pm.id, confirm: true, automatic_payment_methods: { enabled: true, allow_redirects: "never" }, description: `${tag} B` });
      const after = await stripe.paymentMethods.retrieve(pm.id);
      check("B: PI-with-customer-but-no-setup_future_usage leaves PM UNATTACHED (pm.customer null)", after.customer === null);
      const r = await offSession(customer.id, pm.id, "B");
      check("B: off-session reuse fails -> unavailable/not_reusable (was misclassified 'transient' before the fix)", !r.ok && r.result.kind === "unavailable" && r.result.reason === "not_reusable");
    }
    // C — the fixed shape
    {
      const pm = await freshPm();
      await stripe.paymentIntents.create({ amount: 899, currency: "usd", customer: customer.id, payment_method: pm.id, confirm: true, setup_future_usage: "off_session", automatic_payment_methods: { enabled: true, allow_redirects: "never" }, description: `${tag} C` });
      const after = await stripe.paymentMethods.retrieve(pm.id);
      check("C: setup_future_usage=off_session attaches the PM to the customer", after.customer === customer.id && paymentMethodUnusableReason(after, customer.id) === null);
      const r = await offSession(customer.id, pm.id, "C");
      check("C: later off-session renewal charge SUCCEEDS", r.ok && r.status === "succeeded", r.ok ? r.status : r.result.message.slice(0, 80));
    }
    // D — detached
    {
      const pm = await freshPm();
      await stripe.paymentMethods.attach(pm.id, { customer: customer.id });
      await stripe.paymentMethods.detach(pm.id);
      const r = await offSession(customer.id, pm.id, "D");
      check("D: detached PM -> unavailable/not_reusable", !r.ok && r.result.kind === "unavailable" && r.result.reason === "not_reusable");
      let attachErr: unknown = null;
      try { await stripe.paymentMethods.attach(pm.id, { customer: customer.id }); } catch (e) { attachErr = e; }
      check("D: re-attaching a detached PM is refused too (so persistCard's attach fallback cannot rescue it)", attachErr !== null && classifyChargeError(attachErr).kind === "unavailable");
    }
    // E — SCA
    {
      const pm = await freshPm("tok_threeDSecure2Required");
      await stripe.paymentMethods.attach(pm.id, { customer: customer.id });
      const r = await offSession(customer.id, pm.id, "E");
      check("E: SCA-required card -> requires_action", !r.ok && r.result.kind === "requires_action");
    }
    // F — decline
    {
      const pm = await freshPm("tok_visa");
      await stripe.paymentMethods.attach(pm.id, { customer: customer.id });
      // tok_chargeDeclinedInsufficientFunds cannot be attached (attach itself declines), so
      // use a PM created from the decline-on-charge token via a customer-less create+attach fallback:
      let declined: unknown = null;
      try {
        const bad = await stripe.paymentMethods.create({ type: "card", card: { token: "tok_chargeDeclinedInsufficientFunds" } });
        await stripe.paymentIntents.create({ amount: 620, currency: "usd", customer: customer.id, payment_method: bad.id, confirm: true, off_session: true, automatic_payment_methods: { enabled: true, allow_redirects: "never" }, description: `${tag} F` });
      } catch (e) { declined = e; }
      const res = declined ? classifyChargeError(declined) : null;
      check("F: insufficient-funds card -> declined (code insufficient_funds)", !!res && res.kind === "declined" && res.code === "insufficient_funds", res ? `${res.kind}/${"code" in res ? res.code : ""}` : "no error");
    }
    // G — missing
    {
      const r = await offSession(customer.id, "pm_doesnotexist000", "G");
      check("G: nonexistent PM -> unavailable/missing_at_stripe", !r.ok && r.result.kind === "unavailable" && r.result.reason === "missing_at_stripe");
    }
  } finally {
    await stripe.customers.del(customer.id);
    console.log(`\ncleaned up test customer ${customer.id}`);
  }
  console.log(failures === 0 ? "\nALL CHECKS PASSED" : `\n${failures} CHECK(S) FAILED`);
  process.exitCode = failures === 0 ? 0 : 1;
}

main().catch((e) => {
  console.error(e);
  process.exitCode = 1;
});

