import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { stripComments } from "./_source-tools.ts";
import {
  classifyChargeError,
  isNotReusableError,
  paymentMethodUnusableReason,
  unusableCardReasonLabel,
} from "../lib/stripe-charge-errors.ts";
import { dunningView, withBillingGrace, CARD_SUSPEND_DAY, SUSPEND_SLIP_CAP_DAYS } from "../lib/dunning-schedule.ts";

/**
 * 2026-10-01 incident: renewals charging a saved card failed with Stripe's
 * "PaymentMethod was previously used with a PaymentIntent without Customer
 * attachment ... may not be used again", the worker classified it TRANSIENT and
 * retried hourly in silence until the capped suspension day. This suite pins:
 *
 *  (a) the pure classifier (lib/stripe-charge-errors.ts) against the EXACT error
 *      shapes Stripe TEST mode returned on 2026-10-01 (recorded in
 *      scripts/verify-card-reuse-testmode.ts, which replays them live);
 *  (b) the reusability check every card-save path now runs;
 *  (c) the platform-fault grace arithmetic the portal mirrors from the worker;
 *  (d) source tripwires on lib/stripe-cards.ts + worker/billing.ts so the fixes
 *      cannot be quietly undone (same comment-stripped technique as
 *      test/admin-renew-now.test.ts; those modules import Prisma so they are
 *      read as text, never imported).
 */

const STRIPE_NOT_REUSABLE_MESSAGE =
  "The provided PaymentMethod was previously used with a PaymentIntent without Customer attachment, shared with a connected account without Customer attachment, or was detached from a Customer. It may not be used again. To use a PaymentMethod multiple times, you must attach it to a Customer first.";
const STRIPE_ATTACH_REFUSED_MESSAGE =
  "This PaymentMethod was previously used without being attached to a Customer or was detached from a Customer, and may not be used again.";

/** Exactly what stripe-node 22 throws: a StripeInvalidRequestError with NO code. */
const notReusableError = (message = STRIPE_NOT_REUSABLE_MESSAGE) => ({
  type: "StripeInvalidRequestError",
  rawType: "invalid_request_error",
  code: undefined,
  message,
});

/* ---- (a) classifier ------------------------------------------------------- */

test("the live 'may not be used again' error is UNAVAILABLE/not_reusable — never transient", () => {
  const r = classifyChargeError(notReusableError());
  assert.equal(r.ok, false);
  assert.equal(r.kind, "unavailable");
  assert.equal((r as { reason?: string }).reason, "not_reusable");
});

test("Stripe's attach-refusal wording classifies the same way", () => {
  assert.equal(isNotReusableError(notReusableError(STRIPE_ATTACH_REFUSED_MESSAGE)), true);
  const r = classifyChargeError(notReusableError(STRIPE_ATTACH_REFUSED_MESSAGE));
  assert.equal(r.kind, "unavailable");
});

test("resource_missing stays unavailable, now with reason missing_at_stripe", () => {
  const r = classifyChargeError({ type: "StripeInvalidRequestError", rawType: "invalid_request_error", code: "resource_missing", message: "No such PaymentMethod: 'pm_x'" });
  assert.equal(r.kind, "unavailable");
  assert.equal((r as { reason?: string }).reason, "missing_at_stripe");
});

test("a card decline is still a decline, with the issuer's decline_code", () => {
  const r = classifyChargeError({ type: "StripeCardError", rawType: "card_error", code: "card_declined", decline_code: "insufficient_funds", message: "Your card has insufficient funds." });
  assert.equal(r.kind, "declined");
  assert.equal((r as { code?: string }).code, "insufficient_funds");
});

test("authentication_required is requires_action, with the PI id when present", () => {
  const r = classifyChargeError({ type: "StripeCardError", rawType: "card_error", code: "authentication_required", decline_code: "authentication_required", message: "This payment requires authentication.", payment_intent: { id: "pi_1", status: "requires_action" } });
  assert.equal(r.kind, "requires_action");
  assert.equal((r as { paymentIntentId?: string }).paymentIntentId, "pi_1");
});

test("an unrelated invalid_request_error and a plain network Error remain TRANSIENT (the safe default)", () => {
  assert.equal(classifyChargeError({ type: "StripeInvalidRequestError", rawType: "invalid_request_error", message: "Amount must be at least $0.50 usd" }).kind, "transient");
  assert.equal(classifyChargeError(new Error("ECONNRESET")).kind, "transient");
  assert.equal(classifyChargeError({ type: "StripeConnectionError", rawType: "api_connection_error", message: "timeout" }).kind, "transient");
  // A card_error that happens to contain the phrase is still the issuer's call, not ours.
  assert.equal(classifyChargeError({ type: "StripeCardError", rawType: "card_error", code: "card_declined", message: "may not be used again" }).kind, "declined");
  // The phrase alone, without Stripe's invalid_request_error type, does not qualify.
  assert.equal(isNotReusableError(new Error(STRIPE_NOT_REUSABLE_MESSAGE)), false);
});

/* ---- (b) reusability ------------------------------------------------------ */

test("paymentMethodUnusableReason: attached to OUR customer is usable; null is not_reusable; another customer is wrong_customer", () => {
  assert.equal(paymentMethodUnusableReason({ id: "pm_1", customer: "cus_A" }, "cus_A"), null);
  assert.equal(paymentMethodUnusableReason({ id: "pm_1", customer: { id: "cus_A" } }, "cus_A"), null);
  assert.equal(paymentMethodUnusableReason({ id: "pm_1", customer: null }, "cus_A"), "not_reusable");
  assert.equal(paymentMethodUnusableReason({ id: "pm_1" }, "cus_A"), "not_reusable");
  assert.equal(paymentMethodUnusableReason({ id: "pm_1", customer: "cus_B" }, "cus_A"), "wrong_customer");
  assert.equal(paymentMethodUnusableReason({ id: "pm_1", customer: "cus_B" }, null), "wrong_customer");
});

test("every reason has customer-facing wording and unknown falls back safely", () => {
  for (const r of ["missing_at_stripe", "not_reusable", "wrong_customer", null, "something_new"]) {
    assert.ok(unusableCardReasonLabel(r).length > 10);
  }
});

/* ---- (c) grace arithmetic -------------------------------------------------- */

const DAY = 86_400_000;
const expiresAt = new Date("2026-09-30T00:00:00Z");

test("withBillingGrace is a floor on the suspension date, never a shortening", () => {
  const due = new Date(expiresAt.getTime() + 3 * DAY);
  assert.equal(withBillingGrace(due, null).getTime(), due.getTime());
  assert.equal(withBillingGrace(due, new Date(expiresAt.getTime() + 1 * DAY)).getTime(), due.getTime(), "an EARLIER grace must not pull suspension forward");
  const later = new Date(expiresAt.getTime() + 9 * DAY);
  assert.equal(withBillingGrace(due, later).getTime(), later.getTime());
});

test("dunningView: a no-card customer under platform grace is not suspended before the grace ends", () => {
  const now = new Date(expiresAt.getTime() + 1 * DAY);
  const graceUntil = new Date(now.getTime() + 7 * DAY);
  const v = dunningView(
    { expiresAt, dunningStage: 1, dunningNextAt: new Date(now.getTime() + DAY), billingGraceUntil: graceUntil },
    { hasCard: false, graceDays: 3, autoSuspend: true, now },
  );
  assert.equal(v.suspendAt?.getTime(), graceUntil.getTime());
  // and without the grace the same customer would have paused on day 3 — the exact exposure the fix closes
  const bare = dunningView({ expiresAt, dunningStage: 0, dunningNextAt: null }, { hasCard: false, graceDays: 3, autoSuspend: true, now });
  assert.equal(bare.suspendAt?.getTime(), expiresAt.getTime() + 3 * DAY);
});

test("dunningView: the old failure mode — hourly transient reschedules — was capped at CARD_SUSPEND_DAY + slip, with no email", () => {
  // Documents the pre-fix exposure for bujangsmp: dunningNextAt kept moving an
  // hour ahead forever, so suspension landed at the slip cap, day 6 + 4 = 10.
  const now = new Date(expiresAt.getTime() + 9 * DAY);
  const v = dunningView(
    { expiresAt, dunningStage: 0, dunningNextAt: new Date(now.getTime() + 3600_000) },
    { hasCard: true, graceDays: 3, autoSuspend: true, now },
  );
  assert.equal(v.suspendAt?.getTime(), expiresAt.getTime() + (CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS) * DAY);
});

/* ---- (d) source tripwires -------------------------------------------------- */

function code(relative: string): string {
  return stripComments(readFileSync(new URL(relative, import.meta.url), "utf8"));
}
function fn(src: string, declaration: string): string {
  const start = src.indexOf(declaration);
  assert.notEqual(start, -1, `${declaration} not found — has it moved or been renamed?`);
  const rest = src.slice(start + declaration.length);
  const next = rest.search(/\nexport (async )?(function|const|type|class)|\nasync function |\nfunction /);
  return next === -1 ? rest : rest.slice(0, next);
}
const CARDS = code("../lib/stripe-cards.ts");
const BILLING = code("../worker/billing.ts");

test("persistCard refuses to record a PaymentMethod that is not attached to this customer", () => {
  const body = fn(CARDS, "async function persistCard(");
  assert.match(body, /ensurePaymentMethodAttached\(pm, customerId\)/);
  assert.match(body, /if \(!reusable\.ok\)[\s\S]*return false;/);
  assert.match(body, /card\.not_reusable/);
});

test("the mirror onto User never picks a retired card, and set-primary refuses one", () => {
  assert.match(fn(CARDS, "async function mirrorPrimaryCardToUser("), /isPrimary: true, unusableAt: null/);
  assert.match(fn(CARDS, "export async function setPrimaryPaymentCard("), /if \(card\.unusableAt\)/);
});

test("both outstanding-balance checkouts attach a real Customer AND request setup_future_usage", () => {
  for (const decl of ["export async function createOutstandingCheckout(", "export async function createOutstandingEmbedded("]) {
    const body = fn(CARDS, decl);
    assert.match(body, /ensureStripeCustomer\(/, `${decl} must resolve a Stripe customer`);
    assert.match(body, /payment_intent_data: \{ setup_future_usage: "off_session" \}/, `${decl} must save the card attached`);
    assert.doesNotMatch(body, /customer_email/, `${decl} must never fall back to customer_email (no customer = nothing attaches)`);
  }
});

test("the classifier used for charges is the shared pure one, and the dead-card branch retires + graces instead of retrying", () => {
  assert.match(CARDS, /from "\.\/stripe-charge-errors"/);
  assert.doesNotMatch(CARDS, /\nfunction classifyChargeError\(/, "no second classifier may live in stripe-cards.ts");
  const attempt = fn(BILLING, "async function attemptCardRenewal(opts: {");
  assert.match(attempt, /result\.kind === "unavailable"[\s\S]*retireUnusableCard\(/);
  const retire = fn(BILLING, "async function retireUnusableCard(");
  assert.match(retire, /forgetMissingPaymentMethod\(server\.userId, reason\)/);
  assert.match(retire, /billingGraceUntil: graceUntil/);
  assert.match(retire, /PLATFORM_FAULT_GRACE_DAYS/);
  assert.match(retire, /sendCardReaddNotice\(server, cardCents, "first", now\)/);
});

test("suspendDueAt honours billingGraceUntil and commitRenewal clears it", () => {
  assert.match(fn(BILLING, "function suspendDueAt("), /withBillingGrace\(due, server\.billingGraceUntil\)/);
  assert.match(fn(BILLING, "async function commitRenewal(opts: {"), /billingGraceUntil: null/);
  assert.match(fn(BILLING, "async function renewDueServer("), /server\.billingGraceUntil && now < server\.billingGraceUntil[\s\S]*nudgeCardReadd\(/);
});

test("PLATFORM_FAULT_GRACE_DAYS is at least the full card dunning ladder (no shorter runway for OUR fault than for a decline)", () => {
  const m = /const PLATFORM_FAULT_GRACE_DAYS = (\d+);/.exec(BILLING);
  assert.ok(m, "PLATFORM_FAULT_GRACE_DAYS not found");
  assert.ok(Number(m![1]) >= CARD_SUSPEND_DAY, `grace ${m![1]}d is shorter than the decline ladder's suspension day ${CARD_SUSPEND_DAY}`);
});

